var storyContent = {"inkVersion":21,"root":[["#","^title: 书珊城的星辰","/#","#","^author: Tinaski","/#",{"->":"language_select"},["done",{"#f":5,"#n":"g-0"}],null],"done",{"language_select":[["ev","str","^简体中文","/str","/ev",{"*":".^.c-0","flg":20},"ev","str","^English","/str","/ev",{"*":".^.c-1","flg":20},{"c-0":["\n","ev","str","^zh","/str","/ev",{"VAR=":"language","re":true},{"->":"opening_cn"},{"#f":5}],"c-1":["\n","ev","str","^en","/str","/ev",{"VAR=":"language","re":true},{"->":"opening_en"},{"#f":5}]}],{"#f":1}],"opening_cn":[["#","^IMAGE: images/home.webp","/#","^书珊城的风总夹杂着埃兰山脉的燥热。","\n","^但在养父末底改的院子里，角落里那株香桃木却总是静静地绿着。","\n","^我将一片叶子揉碎在指尖，一股清冷的芬芳在热浪中弥散开来。","\n",["ev",{"^->":"opening_cn.0.9.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^深吸这股香气。",{"->":"$r","var":true},null]}],["ev",{"^->":"opening_cn.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^任由叶渣滑落。",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"opening_cn.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.9.s"},[{"#n":"$r2"}],"\n","^在城里传来的喧嚣声中，我感到片刻的安宁。","\n",{"->":".^.^.g-0"},{"#f":5}],"c-1":["ev",{"^->":"opening_cn.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^香气虽好，却盖不住城里传来的喧嚣。","\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^这时，脚步声从门外传来。","\n",["ev",{"^->":"opening_cn.0.g-0.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^“父亲？”",{"->":"$r","var":true},null]}],{"c-2":["ev",{"^->":"opening_cn.0.g-0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":["^末底改走了进来。他的麻衣上沾着尘土，表情显得有些凝重。","\n","^他快步走近我，抿了抿嘴唇，说道：","\n","^“你听说了吗？宫里出大事了。”","\n","^我微微一怔：“出什么事了？”","\n","^末底改环顾四周，声音压得更低了：“几个月前，亚哈随鲁王在宫中大摆宴席，因酒后失态，执意要前王后瓦实提头戴冠冕在群臣面前展示美貌。瓦实提王后傲然拒绝，惹得大王大怒，当场将其废黜并逐出了后宫。”","\n","^“如今，王后的位分空悬，王的谕旨已经传遍了街角，官长正带人挨家挨户搜寻各省的美丽年轻女子。”","\n","^“不久，他们就会到这里来。”","\n","^❖❖❖","\n",["ev",{"^->":"opening_cn.0.g-1.16.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-3","flg":18},{"s":["^“父亲，我不想去那个牢笼。”",{"->":"$r","var":true},null]}],["ev",{"^->":"opening_cn.0.g-1.17.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-4","flg":18},{"s":["^“如果这是命运，我跟他们走。”",{"->":"$r","var":true},null]}],{"c-3":["ev",{"^->":"opening_cn.0.g-1.c-3.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.16.s"},[{"#n":"$r2"}],"\n","^末底改叹了口气：“这不是我们能选择的，孩子。顺从吧。”","\n",{"->":".^.^.^.g-2"},{"#f":5}],"c-4":["ev",{"^->":"opening_cn.0.g-1.c-4.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.17.s"},[{"#n":"$r2"}],"\n","^末底改看着我，眼中的忧虑更甚：“王宫里的事情纷繁复杂，尤其是经历了瓦实提被废的风波后，里面更加伴随着血雨腥风，千万要谨慎。”","\n","^❖❖❖","\n",{"->":".^.^.^.g-2"},{"#f":5}],"#f":5}],"g-2":["^哐哐哐！","\n","^“快开门！”","\n","^❖❖❖","\n","ev","str","^打开门","/str","/ev",{"*":".^.c-5","flg":20},"ev","str","^等待","/str","/ev",{"*":".^.c-6","flg":20},{"c-5":["\n","^我打开门，等在外面的是一众官兵。","\n","^“我们是王派来的，为要寻找美貌的女子。”","\n","^我心头一惊。","\n",{"->":".^.^.^.g-3"},{"#f":5}],"c-6":["\n","^木门被粗暴地推开。几个身着波斯铜甲的士兵鱼贯而入。","\n",{"->":".^.^.^.g-3"},{"#f":5}],"#f":5}],"g-3":["^领头的军官挑了挑眉，冰冷地吐出两个字：“带走。”","\n","^在被拽出家门的混乱中，末底改紧紧抓了一下我的手，低促地耳语道：","\n","^“听着！进去后，抹去你的过去。绝不要提起你的民族，和你的信仰！”","\n","^“从现在起，你叫以斯帖。”","\n","^❖❖❖","\n",["ev",{"^->":"opening_cn.0.g-3.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-7","flg":18},{"s":["^“好的。”",{"->":"$r","var":true},null]}],["ev",{"^->":"opening_cn.0.g-3.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-8","flg":18},{"s":["^“为何？”",{"->":"$r","var":true},null]}],{"c-7":["ev",{"^->":"opening_cn.0.g-3.c-7.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^末底改微微点头。","\n","ev",false,"/ev",{"VAR=":"wish_to_reveal","re":true},{"->":".^.^.^.g-4"},{"#f":5}],"c-8":["ev",{"^->":"opening_cn.0.g-3.c-8.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n","^你不想隐藏自己神的子民的身份。","\n","ev",true,"/ev",{"VAR=":"wish_to_reveal","re":true},{"->":".^.^.^.g-4"},{"#f":5}],"#f":5}],"g-4":["^“别废话。”官兵推搡着我。","\n","ev",false,"/ev",{"VAR=":"esther_identity_revealed","re":true},{"->":"mace_ride_cn"},{"#f":5}]}],{"#f":1}],"mace_ride_cn":[["^我突然被推进了一辆蒙着布的马车。","\n","^车轮滚滚，黑暗中，我反复默念着那个陌生的新名字：以斯帖。","\n","^在波斯语里，这是“星辰”的意思。","\n","^但在我们希伯来语里，它的发音却代表着另一个词——","\n",["ev",{"^->":"mace_ride_cn.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^隐藏。",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"mace_ride_cn.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^马车骤然停下。","\n","^粗布被掀开，刺眼的阳光泼洒下来。映入眼帘的是巍峨的书珊城宫门——那是由无数淡绿色与天蓝色的琉璃砖砌成的巨墙，墙上雕刻着长着翅膀的圣兽，和一排排手持长矛的波斯卫兵。","\n","^❖❖❖","\n",{"->":"chapter_one_cn"},{"#f":5}]}],{"#f":1}],"chapter_one_cn":[[["ev",{"^->":"chapter_one_cn.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^第一章 孤女入宫",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"chapter_one_cn.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^我们被带领着穿过长廊。","\n",["ev",{"^->":"chapter_one_cn.0.g-0.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^地砖",{"->":"$r","var":true},null]}],{"c-1":["ev",{"^->":"chapter_one_cn.0.g-0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"^是用白色、黑色、斑赭色和青色的贵重石头铺成的。阳光穿过高大的立柱照进来，地面反光得像镜子，能映出姑娘们赤裸、颤抖的脚。","\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":[["ev",{"^->":"chapter_one_cn.0.g-1.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^庭院",{"->":"$r","var":true},null]}],{"c-2":["ev",{"^->":"chapter_one_cn.0.g-1.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"^中央有白色、绿色和蓝色的帐子，用细麻绳和紫色绳子系在银环和白玉石柱上。","\n","^这里美得像个梦境，但空气中弥漫的没药香气却沉重得让人喘不过气。","\n",{"->":".^.^.^.g-2"},{"#f":5}],"#f":5}],"g-2":["^一个人影正在不远处出现。","\n",["ev",{"^->":"chapter_one_cn.0.g-2.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-3","flg":18},{"s":["^我转头看向他。",{"->":"$r","var":true},null]}],{"c-3":["ev",{"^->":"chapter_one_cn.0.g-2.c-3.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-3"},{"#f":5}],"#f":5}],"g-3":["^一个长相冷峻的男子，正倒背着手，冷冷地审视着我们这批刚进宫的女子。","\n","^“希该大人。”带领我们的官兵说道。","\n","^我心里一惊，他就是统领女院的大太监希该。","\n","^“下去吧。”","\n","^希该的目光在人群中扫视。姑娘们纷纷低头，有人仍然在小声抽泣。","\n",["ev",{"^->":"chapter_one_cn.0.g-3.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-4","flg":18},{"s":["^我看向他。",{"->":"$r","var":true},null]}],["ev",{"^->":"chapter_one_cn.0.g-3.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-5","flg":18},{"s":["^我低下头。",{"->":"$r","var":true},null]}],{"c-4":["ev",{"^->":"chapter_one_cn.0.g-3.c-4.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^我很好奇，他是什么样的人。","\n",{"->":".^.^.^.g-4"},{"#f":5}],"c-5":["ev",{"^->":"chapter_one_cn.0.g-3.c-5.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n","^我想，要隐藏。","\n",{"->":".^.^.^.g-4"},{"#f":5}],"#f":5}],"g-4":["^“嗯……”希该看着女子们若有所思，然后挥了挥手。","\n","^侍女们端上来几盘极其奢华的波斯饰品。","\n","^“想必大家已经知道了，接下来的十二个月里大家要洁净自己，等待面见王。”","\n","^“王喜欢夺目的女子。”","\n","^希该倒背着手，尖锐的目光扫过每一个人。","\n",["ev",{"^->":"chapter_one_cn.0.g-4.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-6","flg":18},{"s":["^我躲避他的眼神。",{"->":"$r","var":true},null]}],["ev",{"^->":"chapter_one_cn.0.g-4.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-7","flg":18},{"s":["^我看向他，我想知道他究竟想做什么。",{"->":"$r","var":true},null]}],{"c-6":["ev",{"^->":"chapter_one_cn.0.g-4.c-6.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-5"},{"#f":5}],"c-7":["ev",{"^->":"chapter_one_cn.0.g-4.c-7.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-5"},{"#f":5}],"#f":5}],"g-5":["^“这些，是王所赐的礼物。”","\n","^姑娘们开始有些奇怪，有个女子走上前去拿走了一颗镶嵌红宝石的项链。剩下的人便一拥而上，贪婪地争抢着那些闪耀的金银细软。","\n","^❖❖❖","\n","ev","str","^上前，拿了一件昂贵的金饰品","/str","/ev",{"*":".^.c-8","flg":20},"ev","str","^上前，挑一件不那么扎眼的银饰","/str","/ev",{"*":".^.c-9","flg":20},"ev","str","^站在原地不动，什么也不拿","/str","/ev",{"*":".^.c-10","flg":20},{"c-8":["\n","^我顺流而上，随手拿了一串沉重的金项链。","\n","ev",{"VAR?":"king_favor"},1,"-","/ev",{"VAR=":"king_favor","re":true},{"->":".^.^.^.g-6"},{"#f":5}],"c-9":["\n","^我从剩下的器物里选了一枚质朴的银质发簪。","\n",{"->":".^.^.^.g-6"},{"#f":5}],"c-10":["\n","^我双手交叠在身前，平静地看着她们争抢，没有上前。","\n","ev",{"VAR?":"king_favor"},3,"+","/ev",{"VAR=":"king_favor","re":true},{"->":".^.^.^.g-6"},{"#f":5}],"#f":5}],"g-6":["ev",{"VAR?":"king_favor"},9,">","/ev",[{"->":".^.b","c":true},{"b":["\n","^饰品分发结束，希该打量着少女们。","\n","^他慢慢地踱步，然后停在了我的面前。","\n","^他的靴子由上等的皮革制成，没有沾染一丝尘土。他伸出一只苍白、修长的手，用手指挑起了我的下巴。","\n","^希该微微眯起眼，赞许地打量着我。","\n","^“你叫什么名字？”希该的声音尖细，听不出喜怒。","\n","^“……我叫以斯帖。”","\n","^我迎着他的目光，隐去了希伯来语的姓氏。","\n","^“你很好。”他走到我面前，声音放低了些，“那些人以为把自己装饰得像座金山就能取悦君王。她们不知道，君王最厌恶的就是贪婪与市井之气。”","\n","^他转身对身边的女仆吩咐：“带她去最好的厢房。另外，选七个最懂规矩的侍女，日夜服侍她。她应得的份额，一分也不许少。”","\n","^其他姑娘向我投来或嫉妒或羡慕的目光。","\n","^我低头感谢。却不禁一阵害怕，我知道她们的目光有多么危险。","\n","^❖❖❖","\n",{"->":"harem_life_cn"},{"->":".^.^.^.7"},null]}],[{"->":".^.b"},{"b":["\n","^希该冷哼了一声。他没有对任何人表现出偏爱。他的目光扫过那些浑身穿戴得金碧辉煌的姑娘，眼中闪过一丝不易察觉的鄙夷。","\n","^希该冷冷地看着我，甚至没有在我面前停留。","\n","^“带她们去普通厢房。”希该对女仆挥了挥手，语气里满是乏味，“按照规矩，给她们最基本的配给。”","\n","^我被分配到了一个拥挤的房间，四周都是姑娘们的吵闹声。我隐隐感到自己走错了一步。","\n","^我坐在简陋的床榻上，深吸了一口气。没关系，这只是个开始，我必须在接下来的日子里更加加倍小心。","\n","^❖❖❖","\n",{"->":"harem_life_cn"},{"->":".^.^.^.7"},null]}],"nop","\n",{"#f":5}]}],{"#f":1}],"harem_life_cn":[[["ev",{"^->":"harem_life_cn.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^第二章 宫中生活",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"harem_life_cn.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["#","^IMAGE: images/pot.webp","/#","^一年，整整十二个月。","\n","^在书珊城的女院里，时间被拉扯得像波斯夏日的日光一样漫长。","\n","^在这段漫长的时间里，我认识了后宫的总管大太监希该，也认识了一个叫希尼的小侍女。希尼性子温顺，平日里待我极好，常在寒夜里为我多添一盏油灯。","\n","^❖❖❖","\n",["ev",{"^->":"harem_life_cn.0.g-0.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^直到那天清晨。",{"->":"$r","var":true},null]}],{"c-1":["ev",{"^->":"harem_life_cn.0.g-0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":["^希尼像往常一样送来一罐洁身用的没药香膏。她低着头，放下瓷罐后甚至不敢看我的眼睛，神色匆匆地便退了出去。","\n","^待她走后，我舀出少许香膏抹在掌心。一股极其微弱的辛辣微苦之气钻入鼻腔。","\n","^这种气味我很熟悉，是养父告诉我万万不可接触的毒草——乌头——一种能让人容貌尽毁甚至溃烂而死的剧毒。","\n","^看着那罐香膏，我的手微微颤抖。希尼平日里的温柔与刚才慌乱的背影在眼前交织。","\n","^❖❖❖","\n","ev","str","^选择相信，或许她也是受害者","/str","/ev",{"*":".^.c-2","flg":20},"ev","str","^选择警惕，认为她已不可信任","/str","/ev",{"*":".^.c-3","flg":20},{"c-2":["\n","^她或许只是被人胁迫，有不可言说的难言之隐。","\n","^我将香膏悄悄埋进庭院的泥土中，心中虽有隐痛，但仍保留了一份怜悯。","\n","ev",{"VAR?":"courage_points"},1,"+","/ev",{"VAR=":"courage_points","re":true},{"->":".^.^.^.g-2"},{"#f":5}],"c-3":["\n","^在这危险的囚笼里，人心的背叛竟来得这么快。","\n","^我按住冰冷的手腕，强迫自己冷静下来，将香膏悄悄处理掉，警惕地筑起了心中的防线。","\n",{"->":".^.^.^.g-2"},{"#f":5}],"#f":5}],"g-2":["^不久后，真相浮出水面。","\n","^隔壁庭院的侍从用希尼在病中的妹妹相要挟，给了她一袋银币，逼她换掉我的香膏。","\n",["ev",{"^->":"harem_life_cn.0.g-2.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-4","flg":18},{"s":["^希尼确实背叛了我。",{"->":"$r","var":true},null]}],{"c-4":["ev",{"^->":"harem_life_cn.0.g-2.c-4.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-3"},{"#f":5}],"#f":5}],"g-3":["^❖❖❖","\n","^一个月后，风暴降临到了希尼头上。","\n","^希尼在端送昂贵琉璃器皿时失手打碎了圣物，按波斯宫规，她要被当场打断双手，押往边境做苦役。","\n","^看着跪在地上绝望抽泣、浑身发抖的希尼，我知道，这是她命运的绝境。","\n","^❖❖❖","\n","ev","str","^挺身而出，用自己的配给和名义帮助她","/str","/ev",{"*":".^.c-5","flg":20},"ev","str","^冷眼旁观，听之任之","/str","/ev",{"*":".^.c-6","flg":20},{"c-5":["\n","^我走到官兵面前，用希该赐给我的份额替她承担了损失，这使她免去了打断双手的惩罚。","\n","ev",{"VAR?":"king_favor"},2,"+","/ev",{"VAR=":"king_favor","re":true},"^希尼低下头，泣不成声：“以斯帖小姐……你为什么还要救我？”","\n","^我轻轻扶起她的头：“因为生命比恨意更宝贵，希尼。”","\n","^这件事很快传到了大太监希该的耳朵里。","\n","^那天下午，希该独自来到了我的房间。这位见惯了后宫女子勾心斗角的老内侍，用一种全新的目光打量着我。","\n","^“以斯帖，”希该的声音低沉而带着赞叹，“你做的我已经知道了，很好。”","\n","^他微微弯下腰：“王需要的，绝不是一个只会嫉妒争宠的妇人，而是一位拥有承担与怜悯的王后。你身上的这股力量，比任何珠宝都要耀眼。”","\n","^自那天起，他亲自指点我见王时的每一个细节与波斯古礼。","\n",{"->":"king_preparation_cn"},{"#f":5}],"c-6":["\n","^我握紧了手帕，退后了一步。","\n","^希尼被卫兵无情地拖了下去，深宫的冷酷在这一刻展现无遗，你的内心中泛起一阵刺痛。","\n","ev",{"VAR?":"king_favor"},2,"-","/ev",{"VAR=":"king_favor","re":true},{"->":"king_preparation_cn"},{"#f":5}],"#f":5}]}],{"#f":1}],"king_preparation_cn":["^❖❖❖","\n","^十二个月的洁净期，终于满了。","\n","^书珊城上空星辰闪烁，觐见波斯君王亚哈随鲁的日子，近了。","\n","^❖❖❖","\n",{"->":"king_night_cn"},{"#f":1}],"king_night_cn":[[["ev",{"^->":"king_night_cn.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^第三章 星辰与冠冕",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"king_night_cn.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["#","^IMAGE: images/innerscape.webp","/#","^夜幕降临，书珊城被一层幽蓝色的阴影笼罩。","\n","^在被引领前往王的大殿前，侍女们为我端来了成箱的珠宝、金饰与绫罗绸缎。","\n","^“以斯帖小姐，”带路的老内侍低声提醒，“按照规矩，今夜你进去，次日清晨便要退回到女子第二院，由掌管嫔妃的太监沙甲看管。若是王不喜爱你、不再亲自点名召唤你，你这一生……便再也见不到王了。”","\n","^冷酷的规则像冰水一样。这或许是我一生唯一一次的见王的机会。","\n","^我看着那些炫目的饰品，手轻轻放了下来。","\n","^除了大太监希该事先为我挑选的那套素雅的纯白细麻长袍与一缕沉香，我别无所求，丝毫未取。","\n","ev",{"VAR?":"king_favor"},10,">=","/ev",[{"->":".^.b","c":true},{"b":["\n","^沿途的女官与侍卫看着我素净却出尘的气质，眼中纷纷流露出赞叹与敬意。","\n","^希该站在走廊尽头，对我微微颔首，眼里满是欣慰与期许。","\n",{"->":".^.^.^.22"},null]}],[{"->":".^.b"},{"b":["\n","^侍卫们露出了诧异的眼神，似乎不理解为何有人敢赤手空空地去见波斯帝国的君王。","\n",{"->":".^.^.^.22"},null]}],"nop","\n","^❖❖❖","\n",["ev",{"^->":"king_night_cn.0.g-0.26.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^我一步步踏上通往内殿的台阶。",{"->":"$r","var":true},null]}],{"c-1":["ev",{"^->":"king_night_cn.0.g-0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.26.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":["^白玉石柱在浅陶油灯的昏黄光晕中延伸，空气中弥漫着淡淡的没药香气。","\n","^高高的宝座上，坐着一位四十出头的俊朗的男子，身着深蓝色长袍，金黄的冠冕下是潇洒的深褐色卷发。","\n","^❖❖❖","\n",["ev",{"^->":"king_night_cn.0.g-1.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^他便是亚哈随鲁王——波斯帝国的最高统治者。",{"->":"$r","var":true},null]}],{"c-2":["ev",{"^->":"king_night_cn.0.g-1.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-2"},{"#f":5}],"#f":5}],"g-2":["^刚经历过远征希腊的惨败，他的眼神中透着深深的疲惫。见惯了无数堆砌珠宝、瑟瑟发抖或谄媚讨好的女子，当他看到一身白袍、双手交叠、神色平静的我时，眼中闪过了一丝罕见的诧异。","\n","^“抬起头来。”亚哈随鲁王的声音沉重而富有威严，“你叫什么名字？”","\n","^“我叫以斯帖，陛下。”我缓缓抬头，直视着他的目光，目光温和而坦荡。","\n","^王靠回宝座上，按着太阳穴，冷冷地开口：“今夜，我问你三个问题。”","\n","^❖❖❖","\n","^王向前微微倾身，双臂压在宝座扶头上，眼神毒辣如鹰：","\n","^“第一个问题。在这王宫里，每个人面对我时都低头顺服。以斯帖，你觉得他们是对我忠诚，还是对权力恐惧？”","\n","ev","str","^忠诚...","/str","/ev",{"*":".^.c-3","flg":20},"ev","str","^恐惧...","/str","/ev",{"*":".^.c-4","flg":20},{"c-3":["\n","^我微微低头，声音清晰而坚定：“陛下，是忠诚。因为凡目睹过陛下治下公义与威严的人，心中所生出的绝非低微的恐惧，而是由衷的敬重。恐惧不过是转瞬即逝的晨雾，唯有这因敬重而生的忠诚，才能历经风雨而不摇动。”","\n","ev",{"VAR?":"king_favor"},3,"+","/ev",{"VAR=":"king_favor","re":true},"ev",{"VAR?":"courage_points"},1,"+","/ev",{"VAR=":"courage_points","re":true},"^亚哈随鲁王坐直了身体，眼中原本的审视渐渐化为了探究：“你看得很透彻。”","\n",{"->":".^.^.^.g-3"},{"#f":5}],"c-4":["\n","^我恭敬答道：“陛下的威严让人敬畏恐惧。”","\n","ev",{"VAR?":"king_favor"},2,"-","/ev",{"VAR=":"king_favor","re":true},"^王质疑地看了看我。","\n",{"->":".^.^.^.g-3"},{"#f":5}],"#f":5}],"g-3":["^王站起身，缓步走到大殿的高台边缘，俯瞰着外面深沉的夜色。","\n","^“第二个问题。”王的声音带着一丝难以掩饰的孤傲与刺痛，“若是上苍让一位至高无上的君王，尝到了受挫与战败的滋味……你觉得这是神的惩罚，还是神的戏弄？”","\n","ev","str","^山谷低洼积蓄水流，暴风雨让树木根扎更深","/str","/ev",{"*":".^.c-5","flg":20},"ev","str","^胜败乃帝国常事，大王终将重振雄风","/str","/ev",{"*":".^.c-6","flg":20},{"c-5":["\n","^我看着他略显孤单的背影，平静而温和地答道：“都不是陛下。山谷的低洼是为了积蓄更深的水流，暴风雨的侵袭是为了让树木将根扎得更深。智者不在胜败中迷失，而在低谷中学会敬畏与沉淀。”","\n","ev",{"VAR?":"king_favor"},3,"+","/ev",{"VAR=":"king_favor","re":true},"ev",{"VAR?":"courage_points"},2,"+","/ev",{"VAR=":"courage_points","re":true},{"->":".^.^.^.g-4"},{"#f":5}],"c-6":["\n","^我低下头答道：“陛下不必介怀一时之得失，波斯的疆土依然辽阔，大王终将重振威严。”","\n","ev",{"VAR?":"king_favor"},1,"+","/ev",{"VAR=":"king_favor","re":true},{"->":".^.^.^.g-4"},{"#f":5}],"#f":5}],"g-4":["^亚哈随鲁王身形微微一震。我的话像一缕清泉，抚平了他内心深处受挫的焦躁。","\n","^❖❖❖","\n","^王转过身，居高临下地凝视着我的眼睛。","\n","^“第三问。”他的语气极其严肃，“宫廷里到处都是谎言与精心伪装的面具。如果有一天，你发现有人向我隐藏了他的过去与身份，我该如何处置？”","\n","ev","str","^先看清这个人","/str","/ev",{"*":".^.c-7","flg":20},"ev","str","^欺君者当诛","/str","/ev",{"*":".^.c-8","flg":20},{"c-7":["\n","^我抬起头，目光坦荡如星辰：“陛下，有人隐藏是为了谋害，有人隐藏是为了在风暴中存活并守护至爱。看清一个人，不要看他隐藏了什么，要看他在拥有权力与选择时，究竟是选择了施恩，还是选择了伤害。”","\n","ev",{"VAR?":"king_favor"},3,"+","/ev",{"VAR=":"king_favor","re":true},{"->":".^.^.^.g-5"},{"#f":5}],"c-8":["\n","^我低头恭顺地答道：“欺骗君王自然罪不可赦。”","\n","ev",{"VAR?":"king_favor"},1,"-","/ev",{"VAR=":"king_favor","re":true},{"->":".^.^.^.g-5"},{"#f":5}],"#f":5}],"g-5":["^大殿内陷入了长久的死寂。","\n","ev",{"VAR?":"king_favor"},14,">=","/ev",[{"->":".^.b","c":true},{"b":["\n","^王久久地凝视着我。突然，亚哈随鲁王大笑起来。那声音里没有了暴躁与阴霾，取而代之的是久违的畅快与惊艳！","\n","^王快步走下阶梯，亲自伸出手，将躬身站在殿中的我一把扶起！","\n","^“以斯帖！”王的声音响彻整个内殿，“我不会把你送去第二院的，我要你做我的王后。”","\n","^说着，王拉住我的手。","\n","^那一夜，亚哈随鲁王将王后的冠冕戴在了我的头上。","\n","ev",false,"/ev",{"VAR=":"esther_identity_revealed","re":true},{"->":"mordecai_saves_king_cn"},{"->":".^.^.^.9"},null]}],[{"->":".^.b"},{"b":["\n","^王微微摇头：“你很特别，以斯帖。但你还不足以坐上王后的宝座。”","\n",{"->":"king_night_failure_cn"},{"->":".^.^.^.9"},null]}],"nop","\n",{"#f":5}]}],{"#f":1}],"king_night_failure_cn":[[["ev",{"^->":"king_night_failure_cn.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^第四章断章 沉沦的星辰",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"king_night_failure_cn.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["#","^IMAGE: images/sadness.webp","/#","^次日清晨，黎明的曙光尚未划破书珊城的夜空。","\n","^我没有等到王后的冠冕，也没有等到紫色的礼服。","\n","^在两名老太监的押送下，我被送进了“女子第二院”——冷宫。","\n","^门在我身后重重关上。锁链扣紧的声音，彻底斩断了我与外界的一切联系。","\n","^❖❖❖","\n",["ev",{"^->":"king_night_failure_cn.0.g-0.13.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^一年后。",{"->":"$r","var":true},null]}],{"c-1":["ev",{"^->":"king_night_failure_cn.0.g-0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.13.s"},[{"#n":"$r2"}],"^书珊城的风依然带着埃兰山脉的燥热。","\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":["^隔着高高的琉璃墙，我听到了城里传来的喧嚣与哀哭声。","\n","^希尼偷偷塞给我一张羊皮纸残片，上面盖着宰相哈曼的狮子印章与波斯帝国的谕旨：","\n","^“十二月十三日，帝国内一百二十七省，凡犹太人，不分老少妇女孩子，一日之间，悉数杀灭，查抄家产。”","\n","^纸角上，有养父末底改最后的绝笔：“星辰隐没，长夜降临。末底改谨记于此。”","\n",["ev",{"^->":"king_night_failure_cn.0.g-1.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^那一夜",{"->":"$r","var":true},null]}],{"c-2":["ev",{"^->":"king_night_failure_cn.0.g-1.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"^，我跪在冷宫冰冷的地砖上，面向耶路撒冷的方向，泪水砸在干涸的砖缝里。","\n","^书珊城的星辰，彻底熄灭在了这淡蓝色的琉璃墙下。","\n","ev",true,"/ev",{"VAR=":"esther_identity_revealed","re":true},{"->":"bad_ending_cn"},{"#f":5}],"#f":5}]}],{"#f":1}],"bad_ending_cn":["^❖❖❖","\n","^【坏结局：沉沦的星辰】","\n","^你未能获得亚哈随鲁王的喜爱，未能登上王后之位。","\n","^在哈曼的阴谋下，同胞流血成河，犹太民族陷入了沉痛的灾难之中……","\n","^❖❖❖","\n","end",{"#f":1}],"mordecai_saves_king_cn":[[["ev",{"^->":"mordecai_saves_king_cn.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^第四章前奏 宫门的暗流",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"mordecai_saves_king_cn.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["#","^IMAGE: images/intrigue.webp","/#","^戴上王后冠冕后的日子并不轻松。我搬入了奢华的宫殿，但谨遵养父末底改的吩咐，依旧没有向任何人透露我的种族与身世。","\n","^末底改每日依然坐在朝门前，默默关注着后宫中关于我的风吹草动。","\n","^❖❖❖","\n","^直到那一天，朝门前暗流涌动。","\n","^王的两个守门的内侍——辟坛和提列，因对亚哈随鲁王怀恨在心，私下密谋要在王的寝宫中刺杀大王。","\n","^当他们低声商议刺杀细节时，正坐在朝门的末底改将这一切听得清清楚楚。","\n","^末底改心中大惊，刺杀若成，波斯必陷入暴乱，深宫中的我也难保平安。他立刻设法托人将此密报传进了后宫。","\n","#","^IMAGE: images/letter.webp","/#",["ev",{"^->":"mordecai_saves_king_cn.0.g-0.20.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^我收到末底改的密信，不敢有丝毫耽搁。",{"->":"$r","var":true},null]}],{"c-1":["ev",{"^->":"mordecai_saves_king_cn.0.g-0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.20.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":["^我整顿衣冠，立刻奉末底改的名，将内侍谋反的阴谋详细报告了亚哈随鲁王。","\n","^王大受震动，当即下令彻查。波斯禁卫迅速将辟坛和提列缉拿归案，经审讯，谋反罪证确凿！","\n","^二贼被挂在木架上处死。","\n","^亚哈随鲁王十分庆幸避过此劫，命内侍将“犹太人末底改救驾有功”一事，郑重地记录在了波斯的《历代帝王切录》上。","\n","^然而，忙于国政的王随后便淡忘了此事，并未当场赐予末底改任何封赏或爵位。","\n","ev",true,"/ev",{"VAR=":"mordecai_saved_king","re":true},"^❖❖❖","\n","^但这颗看似被埋没的救命种子，已然深深种在了帝国的历史卷轴之中……","\n",{"->":"chapter_four_cn"},{"#f":5}]}],{"#f":1}],"chapter_four_cn":[[["ev",{"^->":"chapter_four_cn.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^第四章 风暴降临",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"chapter_four_cn.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["#","^IMAGE: images/palace.webp","/#","^波斯帝国的星空沉静如水，但书珊城的深宫之外，飓风已至。","\n","^自从亚哈随鲁王提拔哈曼为宰相以来，朝门外的空气便一日比一日窒息。哈曼出入王宫，文武百官皆跪拜迎送，唯独我的养父末底改——他立于朝门前，腰杆如青松般挺直，绝不向哈曼下跪。","\n","^傲慢的哈曼怀恨在心，当他得知末底改是犹太人后，一个极其阴险毒辣的阴谋便在暗中酝酿。","\n","^他用一万他连得银子诱惑王，并在亚哈随鲁王面前掷下名为“普洱”的骰子，抽定了灭绝的凶日。","\n","^盖有波斯王狮子印戒的谕旨通达一百二十七省——","\n","^“十二月十三日，帝国内凡犹太人，不分老少妇女孩子，一日之间，悉数杀灭，查抄家产。”","\n","^❖❖❖","\n",["ev",{"^->":"chapter_four_cn.0.g-0.17.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^这一日",{"->":"$r","var":true},null]}],{"c-1":["ev",{"^->":"chapter_four_cn.0.g-0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.17.s"},[{"#n":"$r2"}],"^，我在后宫听女侍们惊慌地私语，说养父末底正在穿麻衣、蒙灰尘，在朝门外大声哀哭。","\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":["^我心中惊恐，立刻派贴身太监哈他革带着上好的衣服出宫送给他，劝他换下麻衣，但末底改坚决不肯接受。","\n","#","^IMAGE: images/failure.webp","/#","^太监哈他革折返回来，跪在我面前，递上一张抄写的波斯谕旨，以及末底改养父给我的密信。","\n","^“王后殿下，”哈他革的声音颤抖着，“末底改大人命奴转告您……求您冒死进宫觐见王，为本族同胞向王躬身哀求！”","\n","^我握着那张冰冷的谕旨，手心渗出了细密的汗珠。","\n","^我知道，波斯宫廷乃有死律——无论是谁，若不蒙召擅入内院见王，必被治死！除非王向他伸出黄金杖。","\n","ev","str","^向哈他革解释宫中的铁律与危险","/str","/ev",{"*":".^.c-2","flg":20},"ev","str","^表达内心的挣扎与恐惧","/str","/ev",{"*":".^.c-3","flg":20},{"c-2":["\n","^我深吸一口气，低声说道：“哈他革，你随我在宫中多年，自知波斯宫廷的死律……可如今，我已有整整三十日没有蒙王召唤了！”","\n","ev",{"VAR?":"courage_points"},1,"+","/ev",{"VAR=":"courage_points","re":true},{"->":".^.^.^.g-2"},{"#f":5}],"c-3":["\n","^我看着那杀气腾腾的谕旨，声音微颤：“王喜怒无常，若我现在贸然擅闯内院，不仅救不了大家，我自己的性命……恐怕也保不住。”","\n","ev",{"VAR?":"courage_points"},0,"+","/ev",{"VAR=":"courage_points","re":true},{"->":".^.^.^.g-2"},{"#f":5}],"#f":5}],"g-2":["^哈他革领命而去。大殿内只剩下浅陶油灯在风中摇曳，将我的影子拉得极其孤单。","\n","^没过多久，哈他革冒死带回了末底改最后的复信。","\n","^字迹潦草而刚硬，字字句句如重锤般砸在我的灵魂深处：","\n","^“以斯帖，你莫以为你在王宫里，就比所有犹太人安全。”","\n","^“此时你若闭口不言，犹太人必从别处得解脱、蒙拯救；你和你父家必至灭亡。”","\n","^“焉知你得了王后的位分，不是为现今的机会吗？”","\n","^“不是为现今的机会吗……”","\n","^我反复咀嚼着这十二个字。我选择：","\n","ev","str","^冒死去见王","/str","/ev",{"*":".^.c-4","flg":20},"ev","str","^放弃，不去见王","/str","/ev",{"*":".^.c-5","flg":20},{"c-4":["\n","^这一刻，我不再是那个躲在后宫寻求庇护的弱女子。我既得到这最高的冠冕，绝不会明哲保身！","\n","^❖❖❖","\n","^我猛地擦干眼泪，挺直了脊梁，向哈他革下达了最后的指令：","\n","^“哈他革，你回去转告末底改——”","\n","^“招聚书珊城所有的犹太人，为我禁食三天三夜，不吃不喝。我也在宫中同样禁食。”","\n","^我转过身，看着挂在衣架上那套极其华贵的皇家紫长袍与金冠，眼神变得无比清澈而坚定。","\n",["ev","str","^我若死就死吧！","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n","^我按着胸口，向着天上的神发誓：","\n","^“三天之后，我必违例进去见王——我若死，就死吧！”","\n","ev",{"VAR?":"courage_points"},3,"+","/ev",{"VAR=":"courage_points","re":true},"^哈他革行礼，满怀热泪地退出了大殿。","\n","^这幽暗的深宫里，三天的禁食拉开了序幕。","\n",{"->":"chapter_five_cn"},{"#f":5}]}],{"#f":5}],"c-5":["\n","^擅闯内院是必死之罪，而我已经整整三十日未蒙召唤……内心的恐惧最终战胜了意志，我脱力般地瘫坐在椅子上。","\n","^我避开了哈他革焦灼的目光，颤声说道：“哈他革……你回去转告末底改。宫规如铁，我……我实在无能为力。”","\n","^哈他革绝望地深深叩头后，失魂落魄地退出了大殿。","\n",{"->":"bad_ending_cowardice_cn"},{"#f":5}],"#f":5}]}],{"#f":1}],"bad_ending_cowardice_cn":[[["ev",{"^->":"bad_ending_cowardice_cn.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^第四章断章 沉沦的星辰",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"bad_ending_cowardice_cn.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^哈他革离去后的每一分每一秒，对我而言都是煎熬。","\n","^数月的时间在窒息般的沉寂中流逝。","\n","^十二月十三日——哈曼抽定的那个凶日，终究还是来到了。","\n","^同胞的鲜血染红了书珊城的大街小巷，一如末底改叔叔曾经警示过的那样。","\n",["ev",{"^->":"bad_ending_cowardice_cn.0.g-0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^傍晚时分",{"->":"$r","var":true},null]}],{"c-1":["ev",{"^->":"bad_ending_cowardice_cn.0.g-0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"^，大殿的重门被粗暴地推开。","\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":["^宰相哈曼带着一队冷酷的波斯卫士闯了进来。","\n","^“王后殿下，”哈曼嘴角勾起一抹残忍的微笑，“末底改伏诛前，搜出了他与后宫往来的信件。大王刚刚下旨——凡隐藏希伯来血统、欺瞒君王者，与逆贼同罪。”","\n","^我缓缓抬起头，看着哈曼手中冰冷的波斯弯刀，心中只有一股彻底落空的麻木与悲凉。","\n","^冠冕从我的头上滑落，碎在冰冷的大理石板上。","\n","ev",true,"/ev",{"VAR=":"esther_identity_revealed","re":true},"^❖❖❖","\n","^【坏结局：沉沦的星辰】","\n","^因内心的恐惧与动摇，你放弃了这“现今的机会”。","\n","^同胞流血成河，而躲在后宫的你也终究未能幸免于难。","\n","^历史的救赎之门在你面前重重关上……","\n","^❖❖❖","\n","end",{"#f":5}]}],{"#f":1}],"chapter_five_cn":[[["ev",{"^->":"chapter_five_cn.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^第五章 深宫的棋局",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"chapter_five_cn.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^第四天清晨，晨曦划破了书珊城漫长而压抑的夜空。","\n","^三日禁食已毕。侍女为我系上皇家紫绸缎长袍，戴上沉甸甸的金冠。","\n","^生死的赌局已经开场，而我，就是走入死地的那颗棋子。","\n","^❖❖❖","\n","ev","str","^出门进内院","/str","/ev",{"*":".^.c-1","flg":20},{"c-1":["\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":["^我独自走过高耸的白玉石柱，推开了那扇紧闭的重门，迈入了亚哈随鲁王的内院。","\n","^高台的宝座上，亚哈随鲁王猛地抬头。当他的目光落在我身上，看到我一身紫袍、面色苍白却挺直脊梁直视着他时，他眼神中的怒火瞬间被震撼与痛惜取代。","\n","ev",{"VAR?":"king_favor"},12,">=","/ev",[{"->":".^.b","c":true},{"b":["\n","^亚哈随鲁王没有丝毫犹豫，当即挥动了手中那根象征着最高权力与生死的黄金杖！","\n","^他大步跨下阶梯，在众人惊愕的目光中亲自将我扶起。","\n","^“以斯帖！”王的声音里带着关切，“你脸色为何如此苍白？究竟发生了何事，竟让你冒死违例来见我？”","\n",{"->":".^.^.^.11"},null]}],[{"->":".^.b"},{"b":["\n","^亚哈随鲁王停顿了片刻，缓缓向前倾身，向我伸出了手中的黄金杖。","\n","^我快步上前，躬身摸了摸金杖的杖头。我知道，我从死地里活了过来。","\n",{"->":".^.^.^.11"},null]}],"nop","\n","^王紧紧握着我的手，沉声道：“王后以斯帖啊，你要什么？求什么？就是国的一半，也必赐给你！”","\n","#","^IMAGE: images/forgiveness.webp","/#","^❖❖❖","\n","ev","str","^以退为进：邀请王与哈曼赴宴","/str","/ev",{"*":".^.c-2","flg":20},{"c-2":["\n","^我低下头，声音温和而谦卑：“臣妾若在王面前蒙恩，就请王带着宰相哈曼，今日赴臣妾所预备的盛宴。”","\n","ev",{"VAR?":"courage_points"},1,"+","/ev",{"VAR=":"courage_points","re":true},{"->":".^.^.^.g-2"},{"#f":5}],"#f":5}],"g-2":["^王爽快地应允：“传旨哈曼，让他速速准备，赴王后的宴席！”","\n","^宴席之上，美酒如川。","\n","^亚哈随鲁王再次按着酒杯问我：“以斯帖，你究竟有何要求？只要你开口，即便是一半的国度，我也绝不推辞。”","\n","ev","str","^忍耐，推迟至明日再说明","/str","/ev",{"*":".^.c-3","flg":20},"ev","str","^当场指控哈曼的灭族阴谋","/str","/ev",{"*":".^.c-4","flg":20},{"c-3":["\n","^我起身为王斟满美酒，缓缓答道：“臣妾若在王面前蒙恩，求王和哈曼，明日再赴臣妾预备的盛宴。明日……臣妾必按王的话，将心意全盘托出。”","\n","ev",{"VAR?":"courage_points"},2,"+","/ev",{"VAR=":"courage_points","re":true},"^亚哈随鲁王被彻底勾起了好奇心，大笑着应允：“好！明日我与哈曼必准时赴约！”","\n",{"->":"haman_arrogance_cn"},{"#f":5}],"c-4":["\n","^我心中积压已久的愤怒终于破笼而出。我猛地跪倒在地，指着旁边的哈曼大声控诉：","\n","^“大王！这恶人哈曼用巨款蒙蔽了大王，要将臣妾与臣妾的全族斩尽杀绝！”","\n","^大殿内的空气瞬间凝固。","\n","^这突如其来的指控，让没有任何心理准备的亚哈随鲁王脸色骤变。他感到自己在重臣面前失了尊严，更觉得被后宫挟持了国政。","\n","^哈曼当场反驳，指责我包庇违法之民。王冷哼一声，拂袖而去……","\n",{"->":"bad_ending_impatience_cn"},{"#f":5}],"#f":5}]}],{"#f":1}],"haman_arrogance_cn":["^宴罢，哈曼昂首挺胸地走出王宫。","\n","^然而，当他走出朝门，看到末底改依然挺直脊梁、不向他下跪时，哈曼的脸色瞬间阴沉如铁。","\n","^当日回到家中，在他的后院里，一座五丈高的木架连夜拔地而起。哈曼打算次日一早求王下旨，将末底改吊死在这座高架上。","\n","^❖❖❖","\n","^那一夜，书珊城被一层奇异的氛围笼罩。","\n","^主殿之中，至高无上的亚哈随鲁王失眠了。","\n","^王命内侍取来波斯帝国的《历代帝王切录》，在灯下朗读解闷。","\n","^历史的页码偏偏停在了那关键的一页——","\n","^“犹太人末底改，曾揭发内侍辟坛和提列谋弑大王的阴谋，救王于危难。”","\n","^王按着额头，出声问道：“末底改立了此等大功，朝廷赐了他什么尊荣位分没有？”","\n","^内侍查阅后低头答道：“回王……什么也没有赐他。”","\n","^王的眼神瞬间变得冷冽。","\n","^❖❖❖","\n","^次日清晨，天刚蒙蒙亮。极度兴奋的哈曼便早早等在内院，准备求王下旨绞死末底改。","\n","^王将哈曼召入大殿，不等哈曼开口，王便冷冷地提问：","\n","^“哈曼，若王所愿意尊荣人，当如何办理？”","\n","^狂妄至极的哈曼心里窃喜：“王所愿意尊荣的人，除了我，还能有谁？”","\n","^他当即大摇大摆地建议让那人穿御服、骑御马，由贵臣牵马游街。","\n","^亚哈随鲁王斩钉截铁地下旨：","\n","^“好！你速去取御服御马，照你所说的，一丝不漏地向坐在朝门的犹太人末底改行！”","\n","^这句话如同一道五雷轰顶，彻底击碎了哈曼所有的骄傲！他不得不亲手为死敌末底改穿上御服，牵马游街。","\n","^游街结束后，太监已赶到哈曼门前：“宰相大人，王后的第二场盛宴已备妥，大王请您立刻赴宴！”","\n","^❖❖❖","\n",{"->":"chapter_six_cn"},{"#f":1}],"bad_ending_impatience_cn":[[["ev",{"^->":"bad_ending_impatience_cn.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^坏结局 功亏一篑",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"bad_ending_impatience_cn.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^那夜之后，王再未召唤我。","\n","^亚哈随鲁王感到自己在重臣面前失去了尊严，拂袖而去。","\n","^而权倾朝野的哈曼迅速连夜告发我“干预朝政”。","\n","^数日后，末底改被捕，而我也在冷宫中接到了一杯毒酒。","\n","^我拥有冒死觐见的勇气，却唯独缺少了忍耐与等待的智慧。","\n","ev",true,"/ev",{"VAR=":"esther_identity_revealed","re":true},"^❖❖❖","\n","^【坏结局：功亏一篑】","\n","^你因急躁而贸然指控，打草惊蛇。","\n","^未能用智谋掌控局势，最终导致拯救大业彻底功亏一篑……","\n","^❖❖❖","\n","end",{"#f":5}]}],{"#f":1}],"chapter_six_cn":[[["ev",{"^->":"chapter_six_cn.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^第六章 盛宴与雷霆",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"chapter_six_cn.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^第二次盛宴的大殿内，美酒的芬芳与沉香的烟气交织在一起。","\n","^宰相哈曼坐在下首，脸色惨白；亚哈随鲁王看向哈曼的眼神中多了一丝冷冽与审视。","\n","^酒过三巡，王转过身来：“王后以斯帖啊，你要什么？求什么？就是国的一半，也必赐给你！”","\n","^我离席走到大殿中央，深深地叩拜下去。布局已成，雷霆将至。","\n","^❖❖❖","\n","^我抬起头，直视着亚哈随鲁王的眼睛：","\n","^“臣妾若在王面前蒙恩，求王将我的性命赐给我，将我的同胞赐给我！因我和我的同胞被卖了，有人要将我们斩尽杀绝！”","\n","^亚哈随鲁王大怒，拍案而起：“擅敢起意如此行的是谁？！这人在哪里？！”","\n","^我挺直脊梁，缓缓转过身，冰冷的目光如利刃般直指面如死灰的哈曼——","\n","ev","str","^指控哈曼","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^畏缩犹豫","/str","/ev",{"*":".^.c-2","flg":20},{"c-1":["\n","^我抬起手臂，大声宣告：“仇人敌人，就是这恶人哈曼！”","\n","ev",{"VAR?":"courage_points"},3,"+","/ev",{"VAR=":"courage_points","re":true},{"->":"haman_downfall_cn"},{"#f":5}],"c-2":["\n","^我浑身发抖，一时哽咽失声：“陛下……是……是哈曼大人他……”","\n","^亚哈随鲁王皱紧眉头，觉得我拿不出实据。哈曼趁机反咬一口，指责我患有失心之症。","\n",{"->":"bad_ending_hesitation_cn"},{"#f":5}],"#f":5}]}],{"#f":1}],"haman_downfall_cn":["^哈曼如遭雷击，重重地瘫倒在地。","\n","^亚哈随鲁王盛怒下步入御花园压抑怒火。哈曼恐慌万状，爬到我的榻前紧抓我的衣襟求情。","\n","^当王折返回大殿，见此情景怒火冲天：“他竟敢在宫内、在我面前凌辱王后吗？！”","\n","^侍卫当即蒙上哈曼的脸。太监哈他革适时奏道：“哈曼家里还立着一座五丈高的木架，那是他昨日准备用来绞死救驾有功的末底改大人的……”","\n","^亚哈随鲁王吐出了冷酷的判决：“把哈曼挂在上面！”","\n","^❖❖❖","\n","^哈曼伏诛，亚哈随鲁王摘下御印戒指亲手交给了末底改：","\n","^“以我的名义，撰写一道新的谕旨！”","\n","^新谕旨通达全国：允许犹太人在十二月十三日聚集保护性命，拿起武器抵抗攻击他们的人！","\n","^十二月十三日到来，犹太人击退了所有欲图谋害他们的仇敌。","\n","^❖❖❖","\n","^数月后，末底改接替哈曼成为了波斯帝国的宰相，深受爱戴。","\n","^我站在高耸的琉璃墙下，掏出那片早已干枯的香桃木叶。","\n","^末底改走到我的身边，温和地看着我：“从今以后，十二月十四与十五日，将成为我们民族永恒的‘普洱节’。人们将永远记念你的勇敢。”","\n","^风吹过后宫的庭院，扬起了我华贵的紫袍。","\n","^星辰不语，照亮长夜。","\n","#","^IMAGE: images/crown.webp","/#","^❖❖❖","\n","^【真结局：星辰的冠冕】","\n","^你凭借克制与服从顺应天命，凭借信仰与勇气踏过生死，","\n","^又凭着智慧与忍耐在棋局中反败为胜。","\n","^你不仅救了自己的性命，更拯救了整个民族。","\n","^你的名字，将随着普洱节的欢歌，永载史册！","\n","^❖❖❖","\n","end",{"#f":1}],"bad_ending_hesitation_cn":[[["ev",{"^->":"bad_ending_hesitation_cn.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^坏结局 功亏一篑的悲鸣",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"bad_ending_hesitation_cn.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^在关键时刻的犹豫，给了哈曼反咬一口的机会。","\n","^亚哈随鲁王认为我在盛宴上无凭无据污蔑权臣，将我打入冷宫。","\n","^没有了王后的庇护，十二月十三日的凶日如期而至，犹太民族倒在了血泊之中。","\n","^而在冷宫角落里的我，也迎来了赐下的一杯毒酒……","\n","^❖❖❖","\n","^【坏结局：功亏一篑的悲鸣】","\n","^在最关键的指控时刻，你因怯懦犹豫而语无伦次。","\n","^哈曼顺势反咬，使王对你产生厌弃与怀疑。","\n","^大局在临门一脚时彻底崩塌，救赎之路戛然而止……","\n","^❖❖❖","\n","end",{"#f":5}]}],{"#f":1}],"opening_en":[["#","^IMAGE: images/home.webp","/#","^The wind in Susa was always mixed with the sultry heat of the Elamite mountains.","\n","^Yet in the courtyard of my adoptive father, Mordecai, the myrtle tree in the corner always stayed quietly green.","\n","^I crushed a leaf between my fingertips, and a cool fragrance diffused into the heat wave.","\n",["ev",{"^->":"opening_en.0.9.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^Inhale the fragrance.",{"->":"$r","var":true},null]}],["ev",{"^->":"opening_en.0.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^Let the leaf debris slip away.",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"opening_en.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.9.s"},[{"#n":"$r2"}],"\n","^Amidst the din drifting from the city, I felt a moment of peace.","\n",{"->":".^.^.g-0"},{"#f":5}],"c-1":["ev",{"^->":"opening_en.0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^Good as the fragrance was, it could not drown out the clamor from the city.","\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^At this moment, footsteps came from outside the door.","\n",["ev",{"^->":"opening_en.0.g-0.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^\"Father?\"",{"->":"$r","var":true},null]}],{"c-2":["ev",{"^->":"opening_en.0.g-0.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":["^Mordecai walked in. His hemp robe was stained with dust, and his expression looked somewhat solemn.","\n","^He walked up to me quickly, pressed his lips together, and spoke in a low voice:","\n","^\"Have you heard? Something major has happened in the palace.\"","\n","^I was slightly startled: \"What happened?\"","\n","^Mordecai looked around, lowering his voice even further: \"A few months ago, King Ahasuerus held a great banquet in the palace. In a drunken state, he insisted that Queen Vashti wear her royal crown to display her beauty before the officials and the people. Queen Vashti proudly refused, which infuriated the Great King, and he deposed her on the spot and banished her from the harem.\"","\n","^\"Now, the position of queen is vacant, and the king's decree has spread to every street corner. Officials are taking men to search house‑to‑house for beautiful young women from every province.\"","\n","^\"Before long, they will come here.\"","\n","^❖❖❖","\n",["ev",{"^->":"opening_en.0.g-1.16.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-3","flg":18},{"s":["^\"Father, I don't want to go to that cage.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"opening_en.0.g-1.17.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-4","flg":18},{"s":["^\"If this is destiny, I will go with them.\"",{"->":"$r","var":true},null]}],{"c-3":["ev",{"^->":"opening_en.0.g-1.c-3.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.16.s"},[{"#n":"$r2"}],"\n","^Mordecai sighed: \"This is not something we can choose, child. Obey.\"","\n",{"->":".^.^.^.g-2"},{"#f":5}],"c-4":["ev",{"^->":"opening_en.0.g-1.c-4.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.17.s"},[{"#n":"$r2"}],"\n","^Mordecai looked at me, his worry deepening: \"Things in the royal palace are intricate and complex. Especially after the turmoil of Vashti's deposal, it is bound to be fraught with bloodshed. You must be extremely cautious.\"","\n","^❖❖❖","\n",{"->":".^.^.^.g-2"},{"#f":5}],"#f":5}],"g-2":["^Bang! Bang! Bang!","\n","^\"Open the door!\"","\n","^❖❖❖","\n","ev","str","^Open the door","/str","/ev",{"*":".^.c-5","flg":20},"ev","str","^Wait","/str","/ev",{"*":".^.c-6","flg":20},{"c-5":["\n","^I opened the door to find a group of guards waiting outside.","\n","^\"We are sent by the King to search for beautiful women.\"","\n","^A shock ran through my heart.","\n",{"->":".^.^.^.g-3"},{"#f":5}],"c-6":["\n","^The wooden door was shoved open roughly. Several soldiers in Persian bronze armor poured in.","\n",{"->":".^.^.^.g-3"},{"#f":5}],"#f":5}],"g-3":["^The leading officer raised an eyebrow and spat out two cold words: \"Take her.\"","\n","^In the chaos of being dragged out of the house, Mordecai grabbed my hand tightly and whispered urgently:","\n","^\"Listen! Once you go in, erase your past. Never mention your ethnicity or your faith!\"","\n","^\"From now on, your name is Esther.\"","\n","^❖❖❖","\n",["ev",{"^->":"opening_en.0.g-3.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-7","flg":18},{"s":["^\"Alright.\"",{"->":"$r","var":true},null]}],["ev",{"^->":"opening_en.0.g-3.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-8","flg":18},{"s":["^\"Why?\"",{"->":"$r","var":true},null]}],{"c-7":["ev",{"^->":"opening_en.0.g-3.c-7.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^Mordecai nodded slightly.","\n","ev",false,"/ev",{"VAR=":"wish_to_reveal","re":true},{"->":".^.^.^.g-4"},{"#f":5}],"c-8":["ev",{"^->":"opening_en.0.g-3.c-8.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n","^You do not want to hide the identity of God's people.","\n","ev",true,"/ev",{"VAR=":"wish_to_reveal","re":true},{"->":".^.^.^.g-4"},{"#f":5}],"#f":5}],"g-4":["^\"Stop talking nonsense.\" The guards shoved me forward.","\n","ev",false,"/ev",{"VAR=":"esther_identity_revealed","re":true},{"->":"mace_ride_en"},{"#f":5}]}],{"#f":1}],"mace_ride_en":[["^I was suddenly pushed into a cloth‑covered carriage.","\n","^The wheels rolled on, and in the darkness, I kept repeating that strange new name to myself: Esther.","\n","^In Persian, it means \"Star\".","\n","^But in our Hebrew language, its pronunciation represents another word—","\n",["ev",{"^->":"mace_ride_en.0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^Hidden.",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"mace_ride_en.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^The carriage stopped abruptly.","\n","^The coarse cloth was pulled back, and blinding sunlight spilled down. Meeting my eyes were the towering gates of the palace of Susa—massive walls built of countless pale green and sky‑blue glazed bricks, carved with winged holy beasts and rows of Persian guards holding long spears.","\n","^❖❖❖","\n",{"->":"chapter_one_en"},{"#f":5}]}],{"#f":1}],"chapter_one_en":[[["ev",{"^->":"chapter_one_en.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^Chapter 1: The Orphan Enters the Palace",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"chapter_one_en.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^We were led through the long corridor.","\n",["ev",{"^->":"chapter_one_en.0.g-0.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^The floor tiles",{"->":"$r","var":true},null]}],{"c-1":["ev",{"^->":"chapter_one_en.0.g-0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"^ were paved with precious stones of white, black, dark red, and turquoise. Sunlight streamed through the tall pillars, and the floor reflected like a mirror, mirroring the bare, trembling feet of the maidens.","\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":[["ev",{"^->":"chapter_one_en.0.g-1.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^In the center of the courtyard",{"->":"$r","var":true},null]}],{"c-2":["ev",{"^->":"chapter_one_en.0.g-1.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"^ were white, green, and blue hangings, fastened with fine linen and purple cords to silver rings and white marble pillars.","\n","^It was as beautiful as a dream, but the fragrance of myrrh permeating the air was so heavy it made it hard to breathe.","\n",{"->":".^.^.^.g-2"},{"#f":5}],"#f":5}],"g-2":["^A figure appeared not far away.","\n",["ev",{"^->":"chapter_one_en.0.g-2.2.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-3","flg":18},{"s":["^I turned to look at him.",{"->":"$r","var":true},null]}],{"c-3":["ev",{"^->":"chapter_one_en.0.g-2.c-3.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.2.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-3"},{"#f":5}],"#f":5}],"g-3":["^A stern‑looking man stood with his hands behind his back, coldly scrutinizing us girls who had just entered the palace.","\n","^\"Lord Hegai,\" said the officer guiding us.","\n","^A shock went through my heart; this was Hegai, the chief eunuch ruling the women's quarters.","\n","^\"You may leave.\"","\n","^Hegai's gaze swept across the crowd. The girls lowered their heads, and some were still softly sobbing.","\n",["ev",{"^->":"chapter_one_en.0.g-3.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-4","flg":18},{"s":["^I looked at him.",{"->":"$r","var":true},null]}],["ev",{"^->":"chapter_one_en.0.g-3.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-5","flg":18},{"s":["^I lowered my head.",{"->":"$r","var":true},null]}],{"c-4":["ev",{"^->":"chapter_one_en.0.g-3.c-4.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n","^I was curious about what kind of man he was.","\n",{"->":".^.^.^.g-4"},{"#f":5}],"c-5":["ev",{"^->":"chapter_one_en.0.g-3.c-5.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n","^I thought, I must remain hidden.","\n",{"->":".^.^.^.g-4"},{"#f":5}],"#f":5}],"g-4":["^\"Hmm...\" Hegai looked at the women thoughtfully, then waved his hand.","\n","^Maidens brought up several trays of extremely luxurious Persian ornaments.","\n","^\"I presume you all know that for the next twelve months, you must purify yourselves and wait to appear before the King.\"","\n","^\"The King loves dazzling women.\"","\n","^Hegai stood with his hands behind his back, his sharp gaze sweeping over each person.","\n",["ev",{"^->":"chapter_one_en.0.g-4.10.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-6","flg":18},{"s":["^I avoided his gaze.",{"->":"$r","var":true},null]}],["ev",{"^->":"chapter_one_en.0.g-4.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-7","flg":18},{"s":["^I looked at him, wanting to know what he was really up to.",{"->":"$r","var":true},null]}],{"c-6":["ev",{"^->":"chapter_one_en.0.g-4.c-6.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.10.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-5"},{"#f":5}],"c-7":["ev",{"^->":"chapter_one_en.0.g-4.c-7.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-5"},{"#f":5}],"#f":5}],"g-5":["^\"These are gifts bestowed by the King.\"","\n","^The girls began to stir curiously. One woman stepped forward and took a necklace embedded with rubies. The rest swarmed forward, greedily snatching up the shining gold and silver trinkets.","\n","^❖❖❖","\n","ev","str","^Step forward and take an expensive gold ornament","/str","/ev",{"*":".^.c-8","flg":20},"ev","str","^Step forward and choose a less conspicuous silver ornament","/str","/ev",{"*":".^.c-9","flg":20},"ev","str","^Stand still in place and take nothing","/str","/ev",{"*":".^.c-10","flg":20},{"c-8":["\n","^I flowed with the crowd and casually picked up a heavy gold necklace.","\n","ev",{"VAR?":"king_favor"},1,"-","/ev",{"VAR=":"king_favor","re":true},{"->":".^.^.^.g-6"},{"#f":5}],"c-9":["\n","^I selected a simple silver hairpin from the remaining items.","\n",{"->":".^.^.^.g-6"},{"#f":5}],"c-10":["\n","^I folded my hands in front of me, watching them scramble calmly without stepping forward.","\n","ev",{"VAR?":"king_favor"},3,"+","/ev",{"VAR=":"king_favor","re":true},{"->":".^.^.^.g-6"},{"#f":5}],"#f":5}],"g-6":["ev",{"VAR?":"king_favor"},9,">","/ev",[{"->":".^.b","c":true},{"b":["\n","^The distribution of ornaments ended, and Hegai looked the maidens over.","\n","^He paced slowly, then stopped right in front of me.","\n","^His boots were made of fine leather, unblemished by a speck of dust. He extended a pale, slender hand and hooked my chin up with his finger.","\n","^Hegai narrowed his eyes slightly, sizing me up with approval.","\n","^\"What is your name?\" Hegai's voice was thin, betraying neither joy nor anger.","\n","^\"…My name is Esther.\"","\n","^I met his gaze, omitting my Hebrew surname.","\n","^\"You are good.\" He stepped closer to me, lowering his voice a bit, \"Those people think that decorating themselves like a mountain of gold will please the sovereign. They don't know that what the sovereign detests most is greed and vulgarity.\"","\n","^He turned and instructed the maidservant beside him: \"Take her to the best quarters. Furthermore, select seven of the most well‑mannered handmaidens to serve her day and night. Not a single share of what she is due shall be withheld.\"","\n","^The other girls cast glances of jealousy or envy toward me.","\n","^I lowered my head in gratitude. Yet I couldn't help a shiver of fear, knowing how dangerous their gazes were.","\n","^❖❖❖","\n",{"->":"harem_life_en"},{"->":".^.^.^.7"},null]}],[{"->":".^.b"},{"b":["\n","^Hegai gave a cold snort. He showed no partiality to anyone. His gaze swept over the girls dressed in glittering gold, a trace of imperceptible disdain flashing in his eyes.","\n","^Hegai looked at me coldly, not even pausing in front of me.","\n","^\"Take them to the ordinary quarters.\" Hegai waved his hand at the maidservant, his tone full of boredom, \"According to the rules, give them the most basic rations.\"","\n","^I was assigned to a crowded room surrounded by the noisy chatter of the maidens. I sensed faintly that I had made a wrong step.","\n","^I sat on the humble cot and took a deep breath. It doesn't matter, this is only the beginning; I must be twice as careful in the days to come.","\n","^❖❖❖","\n",{"->":"harem_life_en"},{"->":".^.^.^.7"},null]}],"nop","\n",{"#f":5}]}],{"#f":1}],"harem_life_en":[[["ev",{"^->":"harem_life_en.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^Chapter 2: Life in the Palace",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"harem_life_en.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["#","^IMAGE: images/pot.webp","/#","^A year, a full twelve months.","\n","^In the women's quarters of Susa, time was stretched as long as the summer sunlight of Persia.","\n","^During this long stretch of time, I got to know Hegai, the chief eunuch of the harem, and a young handmaiden named Sini. Sini had a gentle temperament and treated me extremely well on ordinary days, often lighting an extra lamp for me on cold nights.","\n","^❖❖❖","\n",["ev",{"^->":"harem_life_en.0.g-0.11.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^Until that morning.",{"->":"$r","var":true},null]}],{"c-1":["ev",{"^->":"harem_life_en.0.g-0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.11.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":["^Sini delivered a jar of myrrh ointment for purification as usual. Lowering her head, she placed the porcelain jar down without even daring to meet my eyes, and hurried out hurriedly.","\n","^After she left, I scooped out a tiny bit of ointment onto my palm. An extremely faint, spicy, and bitter scent drifted into my nasal cavity.","\n","^I was very familiar with this scent; it was a poisonous herb that my adoptive father told me never to touch—aconite—a deadly poison capable of ruining one's appearance and causing skin to rot and fester to death.","\n","^Looking at that jar of ointment, my hands trembled slightly. Sini's usual gentleness and her flustered retreating back intertwined before my eyes.","\n","^❖❖❖","\n","ev","str","^Choose to trust; perhaps she is also a victim","/str","/ev",{"*":".^.c-2","flg":20},"ev","str","^Choose vigilance, believing she can no longer be trusted","/str","/ev",{"*":".^.c-3","flg":20},{"c-2":["\n","^She might just have been coerced by others, harboring unspeakable hardships.","\n","^I secretly buried the ointment in the courtyard's soil. Though there was hidden sorrow in my heart, I still retained a shred of compassion.","\n","ev",{"VAR?":"courage_points"},1,"+","/ev",{"VAR=":"courage_points","re":true},{"->":".^.^.^.g-2"},{"#f":5}],"c-3":["\n","^In this dangerous cage, the betrayal of the human heart came so swiftly.","\n","^I pressed my cold wrist, forcing myself to calm down, quietly disposed of the ointment, and vigilantly built up a line of defense in my heart.","\n",{"->":".^.^.^.g-2"},{"#f":5}],"#f":5}],"g-2":["^Not long after, the truth came to light.","\n","^An attendant from the neighboring courtyard used Sini's ailing younger sister as leverage, giving her a pouch of silver coins to force her into swapping my ointment.","\n",["ev",{"^->":"harem_life_en.0.g-2.4.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-4","flg":18},{"s":["^Sini had indeed betrayed me.",{"->":"$r","var":true},null]}],{"c-4":["ev",{"^->":"harem_life_en.0.g-2.c-4.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.4.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-3"},{"#f":5}],"#f":5}],"g-3":["^❖❖❖","\n","^A month later, the storm descended upon Sini.","\n","^Sini accidentally broke a sacred vessel while carrying an expensive glassware item. According to Persian palace codes, her hands were to be broken on the spot, and she was to be sent away to the border as a forced laborer.","\n","^Looking at Sini kneeling on the ground, weeping desperately and trembling all over, I knew this was the desperate dead end of her destiny.","\n","^❖❖❖","\n","ev","str","^Step forward and help her using your own rations and name","/str","/ev",{"*":".^.c-5","flg":20},"ev","str","^Stand by coldly and let things take their course","/str","/ev",{"*":".^.c-6","flg":20},{"c-5":["\n","^I walked up to the guards and used the share bestowed upon me by Hegai to cover the loss for her, sparing her from having her hands broken.","\n","ev",{"VAR?":"king_favor"},2,"+","/ev",{"VAR=":"king_favor","re":true},"^Sini lowered her head, weeping bitterly: \"Lady Esther... why did you still save me?\"","\n","^I gently lifted her head: \"Because life is more precious than hatred, Sini.\"","\n","^This matter quickly reached the ears of Chief Eunuch Hegai.","\n","^That afternoon, Hegai came to my room alone. This old court eunuch, who had seen countless backstabbing fights among harem women, looked at me with an entirely new gaze.","\n","^\"Esther,\" Hegai said in a low, appreciative voice, \"I already know what you did. Excellent.\"","\n","^He bent down slightly: \"What the King needs is by no means a woman who only knows how to be jealous and vie for favor, but a queen possessed of endurance and compassion. The strength within you shines brighter than any jewel.\"","\n","^From that day on, he personally coached me in every detail and ancient Persian court rite for meeting the King.","\n",{"->":"king_preparation_en"},{"#f":5}],"c-6":["\n","^I clenched my handkerchief and stepped back.","\n","^Sini was ruthlessly dragged away by the guards, displaying the mercilessness of the deep palace in that very moment, and a sharp pain surged in your heart.","\n","ev",{"VAR?":"king_favor"},2,"-","/ev",{"VAR=":"king_favor","re":true},{"->":"king_preparation_en"},{"#f":5}],"#f":5}]}],{"#f":1}],"king_preparation_en":["^❖❖❖","\n","^The twelve‑month period of purification had finally ended.","\n","^Stars twinkled over the sky of Susa, and the day to audience the Persian monarch, Ahasuerus, drew near.","\n","^❖❖❖","\n",{"->":"king_night_en"},{"#f":1}],"king_night_en":[[["ev",{"^->":"king_night_en.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^Chapter 3: Stars and Crown",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"king_night_en.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["#","^IMAGE: images/innerscape.webp","/#","^Night fell, and Susa was draped in a shroud of dark blue shadow.","\n","^Before being led toward the King's Great Hall, maidservants brought me chests of jewelry, gold ornaments, and silk robes.","\n","^\"Lady Esther,\" the old eunuch guiding me reminded in a low voice, \"according to custom, once you enter tonight, you must return by early tomorrow morning to the second women's courtyard, managed by Shaashgaz, the eunuch in charge of the concubines. If the King does not favor you or summon you by name again, for the rest of your life... you will never see the King again.\"","\n","^The ruthless rule was like ice water. This might be my one and only chance to see the King in my lifetime.","\n","^I looked at those dazzling accessories and lowered my hand gently.","\n","^Other than the simple, elegant pure white fine linen robe and a wisp of agarwood picked out beforehand by Chief Eunuch Hegai, I desired nothing else and took absolutely nothing.","\n","ev",{"VAR?":"king_favor"},10,">=","/ev",[{"->":".^.b","c":true},{"b":["\n","^The court ladies and guards along the way looked at my plain yet transcendent temperament, their eyes revealing admiration and respect.","\n","^Hegai stood at the end of the corridor, nodding slightly to me, his eyes full of gratification and expectation.","\n",{"->":".^.^.^.22"},null]}],[{"->":".^.b"},{"b":["\n","^The guards wore surprised expressions, as if unable to understand why anyone would dare go empty‑handed to see the monarch of the Persian Empire.","\n",{"->":".^.^.^.22"},null]}],"nop","\n","^❖❖❖","\n",["ev",{"^->":"king_night_en.0.g-0.26.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^I stepped up the steps leading to the inner hall step by step.",{"->":"$r","var":true},null]}],{"c-1":["ev",{"^->":"king_night_en.0.g-0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.26.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":["^White marble pillars stretched out in the dim, warm glow of earthenware oil lamps, and the air was filled with a faint fragrance of myrrh.","\n","^Upon the high throne sat a handsome man in his early forties, dressed in a deep blue robe, with handsome dark brown curly hair beneath a golden crown.","\n","^❖❖❖","\n",["ev",{"^->":"king_night_en.0.g-1.6.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^He was King Ahasuerus—the supreme ruler of the Persian Empire.",{"->":"$r","var":true},null]}],{"c-2":["ev",{"^->":"king_night_en.0.g-1.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.6.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-2"},{"#f":5}],"#f":5}],"g-2":["^Having just experienced the bitter defeat of his expedition to Greece, his eyes revealed deep exhaustion. Having seen countless women piled with jewelry, trembling with fear, or flattering obsequiously, when he saw me—dressed in a white robe, hands folded, and calm in expression—a rare flash of surprise crossed his eyes.","\n","^\"Lift your head.\" King Ahasuerus's voice was heavy and dignified, \"What is your name?\"","\n","^\"My name is Esther, Your Majesty.\" I slowly raised my head, looking straight into his eyes with a gentle and steady gaze.","\n","^The King leaned back onto his throne, pressing his temples, and spoke coldly:","\n","^\"Tonight, I have three questions for you.\"","\n","^❖❖❖","\n","^The King leaned slightly forward, resting his arms on the throne's armrests, his gaze as piercing as an eagle's:","\n","^\"The first question. In this palace, everyone bows their heads and obeys when facing me. Esther, do you think they are loyal to me, or terrified of power?\"","\n","ev","str","^Loyalty...","/str","/ev",{"*":".^.c-3","flg":20},"ev","str","^Fear...","/str","/ev",{"*":".^.c-4","flg":20},{"c-3":["\n","^I lowered my head slightly, my voice clear and firm: \"Your Majesty, it is loyalty. For those who have witnessed Your Majesty's justice and majesty will generate not petty fear in their hearts, but heartfelt respect. Fear is merely a fleeting morning mist, while only this loyalty born of respect can withstand the storms and remain unshaken.\"","\n","ev",{"VAR?":"king_favor"},3,"+","/ev",{"VAR=":"king_favor","re":true},"ev",{"VAR?":"courage_points"},1,"+","/ev",{"VAR=":"courage_points","re":true},"^King Ahasuerus straightened his body, the original scrutiny in his eyes gradually turning into exploration: \"You see things very thoroughly.\"","\n",{"->":".^.^.^.g-3"},{"#f":5}],"c-4":["\n","^I replied respectfully: \"Your Majesty's majesty inspires awe and fear.\"","\n","ev",{"VAR?":"king_favor"},2,"-","/ev",{"VAR=":"king_favor","re":true},"^The King looked at me skeptically.","\n",{"->":".^.^.^.g-3"},{"#f":5}],"#f":5}],"g-3":["^The King stood up and slowly walked to the edge of the high platform in the hall, overlooking the deep night outside.","\n","^\"The second question.\" The King's voice carried a hint of thinly veiled arrogance and sting, \"If Heaven allowed a supreme sovereign to taste the flavor of setback and defeat... do you think this is a punishment from God, or a tease from God?\"","\n","ev","str","^Valley lows store deeper water; storms make trees root deeper","/str","/ev",{"*":".^.c-5","flg":20},"ev","str","^Victories and defeats are common for an empire; the Great King will eventually restore his glory","/str","/ev",{"*":".^.c-6","flg":20},{"c-5":["\n","^Looking at his slightly lonely back, I replied calmly and gently: \"Neither, Your Majesty. The lowliness of a valley is to store deeper water; the invasion of a storm is to make trees drive their roots deeper. A wise person does not lose themselves in victory or defeat, but learns awe and sedimentation in the low points.\"","\n","ev",{"VAR?":"king_favor"},3,"+","/ev",{"VAR=":"king_favor","re":true},"ev",{"VAR?":"courage_points"},2,"+","/ev",{"VAR=":"courage_points","re":true},{"->":".^.^.^.g-4"},{"#f":5}],"c-6":["\n","^I lowered my head and replied: \"Your Majesty need not mind temporary gains or losses. Persian territory remains vast, and the Great King will eventually restore his majesty.\"","\n","ev",{"VAR?":"king_favor"},1,"+","/ev",{"VAR=":"king_favor","re":true},{"->":".^.^.^.g-4"},{"#f":5}],"#f":5}],"g-4":["^King Ahasuerus's body shook slightly. My words were like a clear spring, smoothing away the restless anxiety deep within his heart.","\n","^❖❖❖","\n","^The King turned around, gazing down condescendingly into my eyes.","\n","^\"The third question.\" His tone was extremely solemn, \"The palace is filled with lies and elaborately disguised masks. If one day, you found someone hiding their past and identity from me, how should I deal with them?\"","\n","ev","str","^First, see the person clearly","/str","/ev",{"*":".^.c-7","flg":20},"ev","str","^Deceivers of the king must be executed","/str","/ev",{"*":".^.c-8","flg":20},{"c-7":["\n","^I raised my head, my gaze as steady as the stars: \"Your Majesty, some hide to plot harm, while others hide to survive a storm and protect their loved ones. To see a person clearly, look not at what they hide, but at whether they choose to bestow grace or cause harm when granted power and choice.\"","\n","ev",{"VAR?":"king_favor"},3,"+","/ev",{"VAR=":"king_favor","re":true},{"->":".^.^.^.g-5"},{"#f":5}],"c-8":["\n","^I replied submissively with my head lowered: \"Deceiving the king is naturally an unpardonable crime.\"","\n","ev",{"VAR?":"king_favor"},1,"-","/ev",{"VAR=":"king_favor","re":true},{"->":".^.^.^.g-5"},{"#f":5}],"#f":5}],"g-5":["^A long, dead silence fell within the hall.","\n","ev",{"VAR?":"king_favor"},14,">=","/ev",[{"->":".^.b","c":true},{"b":["\n","^The King gazed at me for a long time. Suddenly, King Ahasuerus burst out laughing. In that laughter, there was no more irritability or haze, replaced instead by long‑lost relief and amazement!","\n","^The King strode down the steps and personally reached out to pull me up from where I bowed in the hall!","\n","^\"Esther!\" The King's voice resounded through the entire inner hall, \"I will not send you to the second courtyard; I want you to be my queen.\"","\n","^As he spoke, the King took my hand.","\n","^That night, King Ahasuerus placed the queen's crown upon my head.","\n","ev",false,"/ev",{"VAR=":"esther_identity_revealed","re":true},{"->":"mordecai_saves_king_en"},{"->":".^.^.^.9"},null]}],[{"->":".^.b"},{"b":["\n","^The King shook his head slightly: \"You are special, Esther. But you are not yet enough to sit on the queen's throne.\"","\n",{"->":"king_night_failure_en"},{"->":".^.^.^.9"},null]}],"nop","\n",{"#f":5}]}],{"#f":1}],"king_night_failure_en":[[["ev",{"^->":"king_night_failure_en.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^Chapter 4 Interlude: The Sunken Star",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"king_night_failure_en.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["#","^IMAGE: images/sadness.webp","/#","^The next morning, the dawn had not yet broken through the night of Susa.","\n","^I waited neither for the queen's crown nor the purple robe.","\n","^Escorted by two old eunuchs, I was sent into the \"Second Women's Court\"—the cold palace.","\n","^The door closed heavily behind me. The sound of the chains locking tightly completely cut off all connection between me and the outside world.","\n","^❖❖❖","\n",["ev",{"^->":"king_night_failure_en.0.g-0.13.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^A year later.",{"->":"$r","var":true},null]}],{"c-1":["ev",{"^->":"king_night_failure_en.0.g-0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.13.s"},[{"#n":"$r2"}],"^ The wind in Susa still carried the sultry heat of the Elamite mountains.","\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":["^Across the high glazed walls, I heard the clamor and weeping drifting from the city.","\n","^Sini secretly slipped me a fragment of parchment, stamped with the lion seal of Prime Minister Haman and the decree of the Persian Empire:","\n","^\"On the thirteenth day of the twelfth month, among all Jews throughout the hundred and twenty‑seven provinces, young and old, women and children alike, shall be destroyed, killed, and annihilated in a single day, and their property plundered.\"","\n","^At the corner of the paper was adoptive father Mordecai's final brushstroke: \"Stars fade, long night descends. Mordecai records this with caution.\"","\n",["ev",{"^->":"king_night_failure_en.0.g-1.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-2","flg":18},{"s":["^That night",{"->":"$r","var":true},null]}],{"c-2":["ev",{"^->":"king_night_failure_en.0.g-1.c-2.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"^, I knelt on the cold floor tiles of the cold palace, facing the direction of Jerusalem, as my tears dashed into the dry brick cracks.","\n","^The star of Susa was completely extinguished beneath these pale blue glazed walls.","\n","ev",true,"/ev",{"VAR=":"esther_identity_revealed","re":true},{"->":"bad_ending_en"},{"#f":5}],"#f":5}]}],{"#f":1}],"bad_ending_en":["^❖❖❖","\n","^[Bad Ending: The Sunken Star]","\n","^You failed to win the favor of King Ahasuerus and failed to ascend to the throne of queen.","\n","^Under Haman's plot, compatriots bled like rivers, and the Jewish nation fell into deep disaster...","\n","^❖❖❖","\n","end",{"#f":1}],"mordecai_saves_king_en":[[["ev",{"^->":"mordecai_saves_king_en.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^Chapter 4 Prelude: Undercurrents at the Palace Gate",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"mordecai_saves_king_en.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["#","^IMAGE: images/intrigue.webp","/#","^Life after wearing the queen's crown was not easy. I moved into the luxurious palace, but strictly following my adoptive father Mordecai's instructions, I still did not reveal my ethnicity or background to anyone.","\n","^Mordecai still sat daily outside the royal gate, quietly watching the winds and clouds concerning me within the harem.","\n","^❖❖❖","\n","^Until that day, undercurrents stirred before the royal gate.","\n","^Two of the King's gatekeeping eunuchs—Bigthan and Teresh, harboring bitter resentment toward King Ahasuerus—secretly plotted to assassinate the Great King in his bedchamber.","\n","^While they whispered about the details of the assassination, Mordecai, sitting at the royal gate, heard it all crystal clear.","\n","^Mordecai was greatly alarmed; if the assassination succeeded, Persia would surely plunge into rebellion, and I in the deep palace would not be safe either. He immediately arranged for someone to pass this confidential report into the harem.","\n","#","^IMAGE: images/letter.webp","/#",["ev",{"^->":"mordecai_saves_king_en.0.g-0.20.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^I received Mordecai's secret letter without daring to delay a single moment.",{"->":"$r","var":true},null]}],{"c-1":["ev",{"^->":"mordecai_saves_king_en.0.g-0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.20.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":["^I straightened my attire and immediately reported the eunuchs' treasonous plot in detail to King Ahasuerus in Mordecai's name.","\n","^The King was deeply shocked and immediately ordered a thorough investigation. The royal guards quickly apprehended Bigthan and Teresh, and through interrogation, the evidence of treason was ironclad!","\n","^The two traitors were hanged on wooden gallows.","\n","^King Ahasuerus was extremely grateful to have escaped this calamity and ordered the eunuch to record the matter of \"the Jew Mordecai saving the king with meritorious service\" solemnly in the \"Chronicles of the Kings of Persia.\"","\n","^However, the King, busy with state affairs, subsequently forgot about this matter and did not bestow any reward or peerage upon Mordecai on the spot.","\n","ev",true,"/ev",{"VAR=":"mordecai_saved_king","re":true},"^❖❖❖","\n","^Yet this seemingly buried seed of life had already been deeply planted in the historical scroll of the Empire...","\n",{"->":"chapter_four_en"},{"#f":5}]}],{"#f":1}],"chapter_four_en":[[["ev",{"^->":"chapter_four_en.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^Chapter 4: The Storm Descends",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"chapter_four_en.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["#","^IMAGE: images/palace.webp","/#","^The starry sky of the Persian Empire was as serene as water, but outside the deep palace of Susa, a hurricane had arrived.","\n","^Ever since King Ahasuerus promoted Haman to prime minister, the air outside the royal gate grew more suffocating day by day. Whenever Haman entered or left the palace, all civil and military officials bowed and greeted him, except for my adoptive father Mordecai—he stood before the royal gate, his spine as straight as a green pine, absolutely refusing to bow to Haman.","\n","^The arrogant Haman harbored resentment, and upon learning that Mordecai was a Jew, an extremely insidious and vicious plot brewed in secret.","\n","^He tempted the King with ten thousand talents of silver and cast the lot called \"Pur\" before King Ahasuerus to determine the doomed day of annihilation.","\n","^A decree stamped with the Persian king's lion signet reached all one hundred and twenty‑seven provinces—","\n","^\"On the thirteenth day of the twelfth month, all Jews within the empire, young and old, women and children alike, shall be killed and annihilated in a single day, and their property plundered.\"","\n","^❖❖❖","\n",["ev",{"^->":"chapter_four_en.0.g-0.17.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^On this day",{"->":"$r","var":true},null]}],{"c-1":["ev",{"^->":"chapter_four_en.0.g-0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.17.s"},[{"#n":"$r2"}],"^, I heard court maidens whispering in panic within the harem, saying that my adoptive father Mordecai was wearing sackcloth and ashes, crying out loudly outside the royal gate.","\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":["^Filled with terror, I immediately sent my personal eunuch Hathach out of the palace with fine clothing to give to him, urging him to change out of his sackcloth, but Mordecai steadfastly refused to accept it.","\n","#","^IMAGE: images/failure.webp","/#","^Eunuch Hathach returned, kneeling before me and handing over a copied Persian decree as well as a secret letter from my adoptive father Mordecai.","\n","^\"Queen Majesty,\" Hathach's voice trembled, \"Lord Mordecai bids your servant tell you... please risk your life to enter the palace and audience the King, pleading with him on behalf of your kindred!\"","\n","^Clutching that cold decree, cold sweat oozed from the palms of my hands.","\n","^I knew the iron law of the Persian court—no matter who it was, if they entered the inner court to see the King unsummoned, they would be put to death! Unless the King extended his golden scepter toward them.","\n","ev","str","^Explain the iron law and dangers of the palace to Hathach","/str","/ev",{"*":".^.c-2","flg":20},"ev","str","^Express inner struggle and fear","/str","/ev",{"*":".^.c-3","flg":20},{"c-2":["\n","^I took a deep breath and said in a low voice: \"Hathach, you have served by my side in the palace for many years and know the death penalty of the Persian court... Yet right now, I have not been summoned by the King for a full thirty days!\"","\n","ev",{"VAR?":"courage_points"},1,"+","/ev",{"VAR=":"courage_points","re":true},{"->":".^.^.^.g-2"},{"#f":5}],"c-3":["\n","^Looking at the murderous decree, my voice trembled: \"The King is fickle; if I rashly force my way into the inner court now, not only will I fail to save everyone, but my own life... will probably not be saved either.\"","\n","ev",{"VAR?":"courage_points"},0,"+","/ev",{"VAR=":"courage_points","re":true},{"->":".^.^.^.g-2"},{"#f":5}],"#f":5}],"g-2":["^Hathach departed with the order. Only an earthenware oil lamp flickered in the wind inside the great hall, casting my shadow with extreme loneliness.","\n","^Before long, Hathach risked his life to bring back Mordecai's final reply.","\n","^The handwriting was scribbled and rigid, every single word striking like a heavy hammer deep into my soul:","\n","^\"Esther, do not think that because you are in the king's palace you will escape any more than all the other Jews.\"","\n","^\"For if you remain silent at this time, relief and deliverance for the Jews will arise from another place, but you and your father's family will perish.\"","\n","^\"And who knows but that you have come to your royal position for such a time as this?\"","\n","^\"For such a time as this...\"","\n","^I chewed on these twelve words repeatedly. I chose:","\n","ev","str","^Risk death to see the King","/str","/ev",{"*":".^.c-4","flg":20},"ev","str","^Give up and do not go to see the King","/str","/ev",{"*":".^.c-5","flg":20},{"c-4":["\n","^At this moment, I was no longer that weak girl hiding in the harem seeking shelter. Since I had obtained this highest crown, I would never protect myself by staying safe!","\n","^❖❖❖","\n","^I abruptly wiped away my tears, straightened my spine, and gave my final command to Hathach:","\n","^\"Hathach, go back and tell Mordecai—\"","\n","^\"Gather all the Jews in Susa, fast for me three days and nights, neither eating nor drinking. I and my maidens will fast likewise.\"","\n","^I turned around, looking at the extremely luxurious royal purple robe and golden crown hanging on the clothing rack, my gaze turning exceptionally clear and firm.","\n",["ev","str","^If I perish, I perish!","/str","/ev",{"*":".^.c-0","flg":20},{"c-0":["\n","^Pressing my hand to my chest, I swore to the God in heaven:","\n","^\"After three days, I will go to the king, even though it is against the law—and if I perish, I perish!\"","\n","ev",{"VAR?":"courage_points"},3,"+","/ev",{"VAR=":"courage_points","re":true},"^Hathach bowed and tearfully withdrew from the great hall.","\n","^The three‑day fast began in this gloomy deep palace.","\n",{"->":"chapter_five_en"},{"#f":5}]}],{"#f":5}],"c-5":["\n","^Forcing one's way into the inner court was a crime punishable by death, and I had not been summoned for a full thirty days... Internal fear finally defeated my will, and I slumped powerlessly into the chair.","\n","^Avoiding Hathach's anxious gaze, I said in a trembling voice: \"Hathach... go back and tell Mordecai. Palace laws are like iron, and I... I am truly powerless.\"","\n","^After Hathach deeply and despairingly kotowed, he dejectedly retreated from the great hall.","\n",{"->":"bad_ending_cowardice_en"},{"#f":5}],"#f":5}]}],{"#f":1}],"bad_ending_cowardice_en":[[["ev",{"^->":"bad_ending_cowardice_en.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^Chapter 4 Interlude: The Sunken Star",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"bad_ending_cowardice_en.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^Every single minute and second after Hathach's departure was torment for me.","\n","^Months passed in suffocating silence.","\n","^The thirteenth day of the twelfth month—the fateful day drawn by Haman—finally arrived.","\n","^The blood of my compatriots stained the streets and alleys of Susa, just as Uncle Mordecai had once warned.","\n",["ev",{"^->":"bad_ending_cowardice_en.0.g-0.8.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-1","flg":18},{"s":["^By evening",{"->":"$r","var":true},null]}],{"c-1":["ev",{"^->":"bad_ending_cowardice_en.0.g-0.c-1.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.8.s"},[{"#n":"$r2"}],"^, the heavy doors of the great hall were pushed open roughly.","\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":["^Prime Minister Haman strode in with a squad of cold Persian guards.","\n","^\"Queen Majesty,\" Haman's mouth curled into a cruel smile, \"before Mordecai was executed, letters between him and the harem were discovered. The King has just decreed—anyone hiding a Hebrew ancestry or deceiving the sovereign shares the crime of a traitor.\"","\n","^I slowly raised my head, looking at the cold Persian scimitar in Haman's hand, feeling only a numbing and desolate despair.","\n","^The crown slipped from my head, shattering on the cold marble slab.","\n","ev",true,"/ev",{"VAR=":"esther_identity_revealed","re":true},"^❖❖❖","\n","^[Bad Ending: The Sunken Star]","\n","^Due to inner fear and wavering, you gave up this \"opportunity for such a time as this.\"","\n","^Compatriots bled like rivers, and you, hiding in the harem, ultimately failed to escape your fate either.","\n","^The door of historical redemption slammed shut before you...","\n","^❖❖❖","\n","end",{"#f":5}]}],{"#f":1}],"chapter_five_en":[[["ev",{"^->":"chapter_five_en.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^Chapter 5: The Deep Palace Chessboard",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"chapter_five_en.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^On the fourth morning, dawn broke through the long and oppressive night of Susa.","\n","^The three-day fast was complete. A maidservant fastened the royal purple silk robe onto me and placed the heavy golden crown upon my head.","\n","^The gamble of life and death had begun, and I was the chess piece walking into a dead end.","\n","^❖❖❖","\n","ev","str","^Step out into the inner court","/str","/ev",{"*":".^.c-1","flg":20},{"c-1":["\n",{"->":".^.^.^.g-1"},{"#f":5}],"#f":5}],"g-1":["^I walked alone past the towering white marble pillars, pushed open the tightly closed heavy doors, and stepped into King Ahasuerus's inner court.","\n","^Upon the throne on the high platform, King Ahasuerus lifted his head abruptly. When his gaze fell upon me, seeing me in a purple robe, pale yet straightening my spine and looking straight at him, the anger in his eyes was instantly replaced by shock and pity.","\n","ev",{"VAR?":"king_favor"},12,">=","/ev",[{"->":".^.b","c":true},{"b":["\n","^Without the slightest hesitation, King Ahasuerus waved the golden scepter in his hand that symbolized supreme power and life and death!","\n","^He strode down the steps and, amidst the astonished gazes of everyone, personally helped me up.","\n","^\"Esther!\" Concern laced the King's voice, \"Why is your face so pale? What on earth has happened that caused you to risk breaking the law to come see me?\"","\n",{"->":".^.^.^.11"},null]}],[{"->":".^.b"},{"b":["\n","^King Ahasuerus paused for a moment, leaned slowly forward, and extended the golden scepter in his hand toward me.","\n","^I stepped forward quickly, bowing to touch the head of the golden scepter. I knew I had survived from the jaws of death.","\n",{"->":".^.^.^.11"},null]}],"nop","\n","^The King grasped my hand tightly and said in a deep voice: \"Queen Esther, what is your petition? It shall be given you, up to half the kingdom, it shall be requested!\"","\n","#","^IMAGE: images/forgiveness.webp","/#","^❖❖❖","\n","ev","str","^Retreating to advance: Invite the King and Haman to a banquet","/str","/ev",{"*":".^.c-2","flg":20},{"c-2":["\n","^I lowered my head, my voice gentle and humble: \"If it pleases the king, let the king and Prime Minister Haman come today to the banquet that I have prepared for him.\"","\n","ev",{"VAR?":"courage_points"},1,"+","/ev",{"VAR=":"courage_points","re":true},{"->":".^.^.^.g-2"},{"#f":5}],"#f":5}],"g-2":["^The King readily agreed: \"Bring word to Haman to hurry and prepare, to attend the Queen's banquet!\"","\n","^At the banquet, fine wine flowed like a river.","\n","^King Ahasuerus pressed his wine cup and asked me again: \"Esther, what is your request? Whatever you ask, even half the kingdom, I will not refuse.\"","\n","ev","str","^Exercise patience, postponing explanation until tomorrow","/str","/ev",{"*":".^.c-3","flg":20},"ev","str","^Accuse Haman of the extermination plot on the spot","/str","/ev",{"*":".^.c-4","flg":20},{"c-3":["\n","^I stood up to fill the King's cup with fine wine, replying slowly: \"If it pleases the king, may the king and Haman come tomorrow to the banquet I will prepare. Tomorrow... I will do what the king asks and lay bare my whole heart.\"","\n","ev",{"VAR?":"courage_points"},2,"+","/ev",{"VAR=":"courage_points","re":true},"^King Ahasuerus's curiosity was thoroughly piqued, and he laughed heartily as he agreed: \"Good! Tomorrow Haman and I will arrive on time!\"","\n",{"->":"haman_arrogance_en"},{"#f":5}],"c-4":["\n","^The anger that had pent up inside me finally broke its cage. I dropped heavily to my knees, pointing at Haman beside me and crying out in accusation:","\n","^\"Great King! This wicked Haman used a huge sum of money to blind the Great King, intending to slaughter me and my whole kindred!\"","\n","^The air in the great hall froze instantly.","\n","^This sudden accusation caused King Ahasuerus, who had no psychological preparation, to change expression drastically. He felt he had lost dignity in front of his high officials and felt even more that court politics were being hijacked by the harem.","\n","^Haman refuted on the spot, accusing me of harboring law-breaking people. The King snorted coldly and flicked his sleeves, leaving...","\n",{"->":"bad_ending_impatience_en"},{"#f":5}],"#f":5}]}],{"#f":1}],"haman_arrogance_en":["^After the banquet, Haman walked proudly out of the royal palace.","\n","^However, when he stepped out of the royal gate and saw that Mordecai still stood with a straight spine, refusing to bow to him, Haman's expression turned as dark as iron in an instant.","\n","^Upon returning home that day, in his backyard, a fifty-cubit-high gallows rose overnight. Haman intended to beg the King the next morning for a decree to hang Mordecai upon this high gallows.","\n","^❖❖❖","\n","^That night, Susa was enveloped in a peculiar atmosphere.","\n","^In the main hall, the supreme King Ahasuerus suffered from insomnia.","\n","^The King commanded an attendant to fetch the \"Chronicles of the Kings of Persia\" to read aloud to pass the time.","\n","^The page of history happened to stop at that crucial page—","\n","^\"The Jew Mordecai exposed the plot of the eunuchs Bigthan and Teresh to assassinate the Great King, saving the King from peril.\"","\n","^The King pressed his forehead and asked aloud, \"What honor or dignity has been bestowed on Mordecai for this?\"","\n","^The attendant checked and answered with a lowered head, \"Back to the King... nothing has been bestowed upon him.\"","\n","^The King's gaze turned cold instantly.","\n","^❖❖❖","\n","^The next morning, just as dawn broke, an extremely excited Haman waited early in the inner court, ready to beg the King for a decree to hang Mordecai.","\n","^The King summoned Haman into the great hall, and before Haman could speak, the King asked coldly:","\n","^\"Haman, what shall be done for the man the King delights to honor?\"","\n","^The immensely arrogant Haman thought to himself with secret delight: \"Who else could the man the King delights to honor be besides me?\"","\n","^He immediately suggested grandly that the man be dressed in royal robes, mounted on a royal horse, and led through the city street by a noble official.","\n","^King Ahasuerus issued a decisive decree:","\n","^\"Good! Hurry and take the royal robe and the horse, and do just as you have said for Mordecai the Jew, who sits at the royal gate!\"","\n","^This sentence struck like a thunderbolt, completely shattering all of Haman's pride! He had to personally dress his mortal enemy Mordecai in royal robes and lead his horse through the streets.","\n","^After the street procession ended, a eunuch had already hurried to Haman's door: \"Lord Prime Minister, the Queen's second banquet has been prepared, and the Great King invites you to attend immediately!\"","\n","^❖❖❖","\n",{"->":"chapter_six_en"},{"#f":1}],"bad_ending_impatience_en":[[["ev",{"^->":"bad_ending_impatience_en.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^Bad Ending: Falling Short of Success",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"bad_ending_impatience_en.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^After that night, the King never summoned me again.","\n","^King Ahasuerus felt he had lost dignity in front of his high officials and flicked his sleeves away.","\n","^And the all-powerful Haman swiftly reported me for \"interfering in state affairs\" late into the night.","\n","^Days later, Mordecai was arrested, and I received a cup of poisoned wine in the cold palace.","\n","^I possessed the courage to risk a death audience, but I lacked precisely the wisdom of patience and waiting.","\n","ev",true,"/ev",{"VAR=":"esther_identity_revealed","re":true},"^❖❖❖","\n","^[Bad Ending: Falling Short of Success]","\n","^You alarmed the enemy due to impatience and rash accusations.","\n","^Failing to control the situation with wisdom ultimately caused the grand cause of salvation to fall completely short of success...","\n","^❖❖❖","\n","end",{"#f":5}]}],{"#f":1}],"chapter_six_en":[[["ev",{"^->":"chapter_six_en.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^Chapter 6: The Banquet and the Thunderstorm",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"chapter_six_en.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^Inside the great hall of the second banquet, the fragrance of fine wine and the smoke of agarwood intertwined.","\n","^Prime Minister Haman sat at the lower seat, his face pale; King Ahasuerus's gaze toward Haman held an extra trace of coldness and scrutiny[cite: 2].","\n","^When the wine had been served three times, the King turned around: \"Queen Esther, what is your petition? It shall be given you, up to half the kingdom, it shall be requested!\"","\n","^I stepped out of my seat to the center of the great hall and bowed deeply. The layout was set, and the thunderstorm was about to strike.","\n","^❖❖❖","\n","^I raised my head, looking straight into King Ahasuerus's eyes:","\n","^\"If I have found favor in your eyes, O king, and if it pleases the king, grant me my life—this is my petition. And spare my people—this is my request. For I and my people have been sold to be destroyed, slain, and annihilated!\"","\n","^King Ahasuerus burned with anger and sprang to his feet: \"Who is he, and where is he, who has presumed in his heart to do such a thing?!\"","\n","^Straightening my spine, I slowly turned around, my cold gaze pointing like a sharp blade straight at the pale-faced Haman—","\n","ev","str","^Accuse Haman","/str","/ev",{"*":".^.c-1","flg":20},"ev","str","^Shrink back and hesitate","/str","/ev",{"*":".^.c-2","flg":20},{"c-1":["\n","^I raised my arm and proclaimed loudly: \"The adversary and enemy is this wicked Haman!\"","\n","ev",{"VAR?":"courage_points"},3,"+","/ev",{"VAR=":"courage_points","re":true},{"->":"haman_downfall_en"},{"#f":5}],"c-2":["\n","^Trembling all over, I choked up and lost my voice for a moment: \"Your Majesty... it is... it is Lord Haman...\"","\n","^King Ahasuerus knitted his brows tightly, feeling I lacked solid evidence. Haman seized the opportunity to counter-accuse, claiming I suffered from a mental affliction.","\n",{"->":"bad_ending_hesitation_en"},{"#f":5}],"#f":5}]}],{"#f":1}],"haman_downfall_en":["^Haman was struck as if by lightning, collapsing heavily to the ground.","\n","^In a fit of fury, King Ahasuerus stepped into the royal garden to cool his anger. Terrified, Haman crawled to my couch and grabbed my robe to beg for mercy.","\n","^When the King returned to the great hall and saw this scene, his anger blazed to the heavens: \"Will he even assault the queen while I am in the house?!\"","\n","^The guards immediately covered Haman's face. Eunuch Hathach chimed in timely: \"There is a gallows fifty cubits high standing at Haman's house, which he made yesterday to hang Mordecai, who spoke up to save the King...\"","\n","^King Ahasuerus spat out the cold verdict: \"Hang him on it!\"","\n","^❖❖❖","\n","^Haman was executed, and King Ahasuerus took off his signet ring and handed it personally to Mordecai:","\n","^\"Write a new decree in my name!\"","\n","^The new decree reached across the country: permitting the Jews to gather on the thirteenth day of the twelfth month to protect their lives, taking up arms to resist those who attacked them!","\n","^When the thirteenth day of the twelfth month arrived, the Jews repulsed all enemies who sought to harm them.","\n","^❖❖❖","\n","^Months later, Mordecai succeeded Haman as the Prime Minister of the Persian Empire, deeply beloved.","\n","^I stood beneath the towering glazed walls, pulling out that long-dried myrtle leaf.","\n","^Mordecai walked to my side, looking at me gently: \"From now on, the fourteenth and fifteenth days of the twelfth month will become our nation's eternal 'Purim'. People will forever remember your courage.\"","\n","^The wind blew across the courtyard of the harem, lifting my luxurious purple robe.","\n","^The stars spoke not a word, yet they illuminated the long night.","\n","#","^IMAGE: images/crown.webp","/#","^❖❖❖","\n","^[True Ending: The Crown of Stars]","\n","^You conformed to destiny through restraint and obedience, stepped through life and death with faith and courage,","\n","^and turned defeat into victory on the chessboard with wisdom and patience.","\n","^You not only saved your own life, but saved an entire nation.","\n","^Your name will be eternally recorded in history alongside the joyful songs of Purim!","\n","^❖❖❖","\n","end",{"#f":1}],"bad_ending_hesitation_en":[[["ev",{"^->":"bad_ending_hesitation_en.0.0.$r1"},{"temp=":"$r"},"str",{"->":".^.s"},[{"#n":"$r1"}],"/str","/ev",{"*":".^.^.c-0","flg":18},{"s":["^Bad Ending: The Lament of Falling Short",{"->":"$r","var":true},null]}],{"c-0":["ev",{"^->":"bad_ending_hesitation_en.0.c-0.$r2"},"/ev",{"temp=":"$r"},{"->":".^.^.0.s"},[{"#n":"$r2"}],"\n",{"->":".^.^.g-0"},{"#f":5}],"g-0":["^Hesitation at the critical moment gave Haman the chance to counter-attack.","\n","^King Ahasuerus deemed that I slandered a high official without evidence at the banquet and cast me into the cold palace.","\n","^Without the Queen's protection, the doomed day of the thirteenth month arrived as scheduled, and the Jewish nation fell in pools of blood.","\n","^And I, in the corner of the cold palace, also ushered in the cup of poisoned wine bestowed upon me...","\n","^❖❖❖","\n","^[Bad Ending: The Lament of Falling Short]","\n","^At the most crucial moment of accusation, you stumbled and stammered due to cowardice and hesitation.","\n","^Haman smoothly turned the tables, causing the King to develop aversion and suspicion toward you.","\n","^The grand situation collapsed completely at the final kick, and the path of redemption abruptly ended...","\n","^❖❖❖","\n","end",{"#f":5}]}],{"#f":1}],"global decl":["ev",10,{"VAR=":"king_favor"},0,{"VAR=":"haman_suspicion"},false,{"VAR=":"esther_identity_revealed"},10,{"VAR=":"courage_points"},false,{"VAR=":"mordecai_saved_king"},false,{"VAR=":"wish_to_reveal"},"str","^zh","/str",{"VAR=":"language"},"/ev","end",null],"#f":1}],"listDefs":{}};